
'use strict';
const HOUSES={Gryffondor:{accent:'#9f303c',accent2:'#e0b95c',crest:'♌',desc:'Courage, audace et détermination.'},Serpentard:{accent:'#27735d',accent2:'#c5d4ca',crest:'♜',desc:'Ambition, ingéniosité et volonté.'},Serdaigle:{accent:'#315b91',accent2:'#bd8a55',crest:'✧',desc:'Curiosité, esprit et créativité.'},Poufsouffle:{accent:'#b58b2d',accent2:'#171717',crest:'❖',desc:'Loyauté, patience et justice.'}};
const DEFAULT_SETTINGS={fontScale:1,reading:760,contrast:false,reduced:false,dialogueSpeed:'normal',confirm:true};
const initialState=()=>({started:false,page:'home',setupStep:0,character:{name:'',pronouns:'',age:11,appearance:'',personality:'',qualities:[],flaws:[],ambition:'',family:'',childhood:'',secret:'',wood:'',core:'',length:'',flexibility:'',animal:'',house:'',patronus:'Inconnu'},quiz:{},year:1,chapter:0,scene:0,health:100,magic:100,galleons:25,housePoints:0,reputation:{students:0,professors:0,house:0},skills:{Sortilèges:0,Potions:0,Défense:0,Métamorphose:0},spells:['Lumos','Nox'],inventory:['Baguette magique','Uniforme de Poudlard','Carnet personnel'],relations:{'Harry Potter':0,'Ron Weasley':0,'Hermione Granger':0,'Neville Londubat':0,'Drago Malefoy':-1},quests:[],journal:[],clues:[],flags:{},choices:[],settings:{...DEFAULT_SETTINGS},lastSave:null,patronusStage:0,quidditch:{trained:0,wins:0},houseCup:0,duel:{active:false,enemy:'',enemyHP:100,round:0},calendar:{season:'Automne',week:1}});
let S=initialState();let activeSlot=0;let toastTimer;const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safeJSON=x=>{try{return JSON.parse(x)}catch{return null}};
const YEARS=[
[{title:'Une lettre sous la pluie',place:'La maison',text:'La pluie dessine des lignes argentées sur la vitre. Depuis quelques semaines, des détails impossibles troublent ton quotidien : une serrure qui s’ouvre seule, une flamme qui danse quand tu es contrarié, un rêve récurrent où une chouette te fixe depuis une tour.',choices:[{label:'Confier tes inquiétudes à ta famille',desc:'Choisir la confiance et demander des réponses.',effect:{relations:{'Harry Potter':1},flags:{familyConfided:true},journal:'Tu as décidé de ne pas garder tes inquiétudes pour toi.'},next:'Un silence s’installe, puis une vérité longtemps retenue commence à émerger.'},{label:'Garder tes questions pour toi et chercher des indices',desc:'Observer avant de parler.',effect:{skills:{Sortilèges:1},flags:{quietObserver:true},clue:'Une enveloppe crème portant une adresse écrite à l’encre verte.',journal:'Tu as choisi d’observer les signes avant de demander des explications.'},next:'Tu notes chaque détail dans un carnet. Au fond d’un tiroir, une enveloppe crème attend depuis bien plus longtemps que tu ne le pensais.'}]},
{title:'Le chemin de Traverse',place:'Londres magique',text:'Derrière une façade discrète, le monde s’ouvre sur une rue animée où les vitrines semblent respirer. Le métal des chaudrons tinte, des plumes grattent toutes seules le papier et une chouette pousse un cri indigné depuis une cage. Pour la première fois, tu comprends que l’étrange a des règles — et une histoire.',choices:[{label:'Prendre le temps de parler aux commerçants',desc:'Écouter, apprendre et découvrir un détail utile.',effect:{galleons:-3,flags:{merchantFriend:true},journal:'Tu as pris le temps de découvrir les habitudes du monde magique.'},next:'Un commerçant te glisse un conseil à voix basse : à Poudlard, les meilleurs secrets se cachent rarement derrière les portes les plus impressionnantes.'},{label:'Chercher ta baguette sans détour',desc:'Suivre l’appel discret d’une boutique ancienne.',effect:{skills:{Sortilèges:1},flags:{wandInstinct:true},journal:'Tu as suivi ton intuition jusqu’à la boutique de baguettes.'},next:'Dans une boutique étroite, une baguette semble vibrer à ton approche. Le fabricant t’observe avec un intérêt nouveau.'}]},
{title:'Le Poudlard Express',place:'Voie 9¾',text:'La vapeur rouge du train enveloppe le quai. Des familles s’embrassent, des malles roulent sur les pavés et des hiboux protestent dans leurs cages. Tu montes à bord avec le sentiment étrange que la personne que tu étais ce matin ne sera déjà plus tout à fait celle que tu seras ce soir.',choices:[{label:'Rejoindre un compartiment où des élèves discutent',desc:'Faire le premier pas vers de nouvelles amitiés.',effect:{relations:{'Ron Weasley':1,'Hermione Granger':1},journal:'Dans le train, tu as choisi la rencontre plutôt que la solitude.'},next:'La conversation dérive des friandises aux matières scolaires. Quelqu’un pose une question qui te fait rire, et la nervosité retombe.'},{label:'Choisir un compartiment calme et observer le paysage',desc:'Prendre le temps de t’habituer à ce nouveau monde.',effect:{flags:{trainAlone:true},clue:'Un billet froissé portant une note au sujet d’un couloir interdit.',journal:'Le voyage t’a offert un moment de calme et un indice inattendu.'},next:'Sous la banquette, tu trouves un billet froissé. Une phrase à moitié effacée mentionne un couloir où personne ne devrait se rendre seul.'}]},
{title:'La cérémonie de répartition',place:'Grande Salle',text:'Des milliers de bougies flottent au-dessus des tables. Le plafond reflète un ciel nocturne profond, et les quatre bannières ondulent sans le moindre souffle. Quand ton nom est appelé, les conversations s’éteignent peu à peu. Le Choixpeau descend sur ta tête et semble écouter quelque chose que tu n’as jamais formulé à voix haute.',choices:[{label:'Penser au courage qu’il faut pour recommencer',desc:'Tu acceptes l’incertitude et avances malgré elle.',effect:{quiz:{Gryffondor:2},journal:'Lors de la cérémonie, tu as pensé au courage nécessaire pour avancer.'},next:'Le Choixpeau remue légèrement. « Le courage n’est pas toujours l’absence de peur… »'},{label:'Penser à la personne que tu veux devenir',desc:'Ton ambition trace une direction, sans tout décider.',effect:{quiz:{Serpentard:2},journal:'Tu as pensé à la personne que tu souhaites devenir.'},next:'Le Choixpeau semble amusé. « Voilà une question plus intéressante que celle de savoir qui tu es aujourd’hui. »'},{label:'Penser aux questions que tu veux résoudre',desc:'La curiosité ouvre des portes inattendues.',effect:{quiz:{Serdaigle:2},journal:'Tu as suivi ta curiosité pendant la cérémonie.'},next:'Le Choixpeau s’attarde. « Un esprit qui cherche peut parfois trouver bien davantage que des réponses. »'},{label:'Penser aux personnes que tu veux protéger',desc:'La loyauté donne un sens à tes choix.',effect:{quiz:{Poufsouffle:2},journal:'Tu as placé la loyauté au centre de tes pensées.'},next:'Le Choixpeau paraît satisfait. « Les liens que l’on choisit sont parfois les plus solides. »'}]}
],
[{title:'Un couloir qui n’apparaît pas sur les plans',place:'Poudlard',text:'Un courant d’air traverse un corridor pourtant fermé. Sur la pierre, une marque semble apparaître puis disparaître à la lumière de ta baguette. Tu reconnais un motif aperçu dans tes notes. Il ne s’agit peut-être que d’une coïncidence — mais quelque chose t’invite à regarder de plus près.',choices:[{label:'Étudier la marque avec méthode',desc:'Comparer les détails et noter les différences.',effect:{skills:{Sortilèges:1},clue:'Une marque ancienne réagit à la lumière magique.',journal:'Tu as découvert une marque ancienne dans un couloir.'},next:'Les lignes s’assemblent lorsque tu déplaces la lumière. Le motif ne donne pas une réponse, mais il révèle que la pierre a été déplacée.'},{label:'Demander discrètement conseil à un camarade',desc:'La confiance peut ouvrir une piste.',effect:{relations:{'Hermione Granger':1},flags:{askedClassmate:true},journal:'Tu as choisi de confronter tes observations à celles d’un camarade.'},next:'Ton camarade reconnaît un détail dans le motif. Il n’a pas la solution, mais sait où chercher un vieux registre.'}]},
{title:'Une promesse au bord du lac',place:'Parc de Poudlard',text:'La surface du lac reflète les tours comme un miroir sombre. Après une journée de cours, un ami te confie une inquiétude qu’il n’a osé partager avec personne. Il ne te demande pas de résoudre son problème ; seulement de prendre sa parole au sérieux.',choices:[{label:'Promettre de l’aider, même si cela prend du temps',desc:'Un engagement qui pourra compter plus tard.',effect:{relations:{'Neville Londubat':2},flags:{lakePromise:true},journal:'Au bord du lac, tu as fait une promesse importante.'},next:'La tension quitte un peu son visage. Une promesse ne résout pas tout, mais elle donne un point de départ.'},{label:'Écouter sans promettre ce que tu ignores pouvoir tenir',desc:'La sincérité plutôt que les grandes déclarations.',effect:{relations:{'Neville Londubat':1},reputation:{students:1},journal:'Tu as choisi l’honnêteté plutôt qu’une promesse incertaine.'},next:'Il hoche la tête, soulagé que tu ne lui offres pas de réponse facile. La confiance peut aussi commencer par une limite claire.'}]}
],
[{title:'La carte aux marges effacées',place:'Bibliothèque',text:'Un volume oublié semble avoir été consulté récemment. Dans les marges, une écriture ancienne évoque une pièce qui ne se montre qu’à ceux qui cherchent quelque chose sans savoir exactement quoi. Plusieurs lignes ont été grattées, mais une date demeure lisible.',choices:[{label:'Comparer la date avec le calendrier de l’école',desc:'Chercher une logique avant de tirer une conclusion.',effect:{skills:{Sortilèges:1},clue:'La date correspond à une ancienne fermeture de couloir.',journal:'Tu as commencé à comparer les indices du vieux volume.'},next:'La date coïncide avec une modification des plans de l’école. Quelqu’un a voulu que cet endroit cesse d’être trouvé.'},{label:'Interroger la bibliothécaire sur le livre',desc:'Un témoignage peut compléter un document.',effect:{reputation:{professors:1},flags:{askedLibrarian:true},journal:'Tu as demandé de l’aide pour comprendre un document ancien.'},next:'La bibliothécaire ne révèle rien de direct, mais t’indique une section d’archives rarement consultée.'}]},
{title:'Une magie qui répond aux souvenirs',place:'Salle de classe',text:'Pendant un exercice de défense, une incantation reste inerte. Le professeur te demande de ralentir et de comprendre ce qui manque. La magie n’est pas un mécanisme que l’on force : elle dépend aussi de l’intention, de la concentration et de ce que tu es prêt à affronter.',choices:[{label:'Recommencer en te concentrant sur une personne importante',desc:'La mémoire donne un sens à ton effort.',effect:{magic:15,patronusStage:1,journal:'Tu as découvert que tes souvenirs peuvent guider ta concentration magique.'},next:'Une lueur argentée frémit un instant, fragile comme une respiration. Ce n’est pas encore un Patronus, mais la magie a répondu.'},{label:'Décomposer le geste et corriger ta technique',desc:'La patience construit la maîtrise.',effect:{skills:{Défense:1},magic:10,journal:'Tu as amélioré ta technique en reprenant chaque étape.'},next:'Le sort finit par produire un éclat net. Tu comprends mieux le mouvement, et tu sais sur quoi travailler ensuite.'}]}
],
[{title:'Le prix d’une vérité',place:'Poudlard',text:'Les indices commencent à se rejoindre, mais ils désignent des personnes qui n’ont pas toutes les mêmes intentions. Une accusation hâtive pourrait faire du mal à quelqu’un qui n’y est pour rien. Garder le silence, cependant, laisserait peut-être une injustice se poursuivre.',choices:[{label:'Présenter les faits sans accuser au-delà des preuves',desc:'La prudence protège la vérité.',effect:{reputation:{professors:1,students:1},journal:'Tu as choisi de présenter les preuves sans extrapoler.'},next:'La discussion est tendue, mais personne ne peut prétendre que tu as déformé les faits. Une piste reste ouverte.'},{label:'Confronter directement la personne concernée',desc:'Prendre le risque d’une réaction immédiate.',effect:{reputation:{students:-1},flags:{directConfrontation:true},journal:'Tu as confronté directement une personne liée au mystère.'},next:'La réaction est vive. Tu n’obtiens pas toutes les réponses, mais un détail dans sa défense contredit ce que tu avais entendu.'}]},
{title:'L’épreuve des alliances',place:'Grande Salle',text:'À mesure que l’année avance, les conversations changent de ton. Les élèves se souviennent de tes actes, pas seulement de tes paroles. Quand une difficulté collective surgit, plusieurs regards se tournent vers toi : certains espèrent que tu aideras, d’autres attendent de voir quel camp tu choisiras.',choices:[{label:'Rassembler les personnes qui se font confiance',desc:'Construire une alliance imparfaite mais sincère.',effect:{reputation:{students:2,house:1},housePoints:5,journal:'Tu as réuni des élèves autour d’un objectif commun.'},next:'L’accord n’est pas parfait, mais chacun sait ce qu’il peut apporter. Pour la première fois, les différences deviennent une force.'},{label:'Agir discrètement avec les personnes les plus fiables',desc:'Un petit groupe peut avancer sans attirer l’attention.',effect:{flags:{quietAlliance:true},relations:{'Hermione Granger':1},journal:'Tu as privilégié une alliance discrète et ciblée.'},next:'Vous vous répartissez les tâches sans bruit. Le résultat est modeste en apparence, mais la piste progresse.'}]}
],
[{title:'Les limites de la magie',place:'Salle de classe',text:'Une formule interdite circule sous forme de rumeur. On la décrit comme une solution rapide à un problème qui semble insoluble. Les explications sont contradictoires, et les risques, eux, sont bien réels. Tu peux chercher à comprendre ce pouvoir sans l’utiliser, ou tenter d’en éprouver les limites.',choices:[{label:'Étudier les risques avant toute décision',desc:'Comprendre n’oblige pas à céder à la tentation.',effect:{skills:{Défense:1},reputation:{professors:1},journal:'Tu as choisi d’étudier les risques avant de toucher à une magie dangereuse.'},next:'Les notes révèlent un coût souvent omis dans les récits flatteurs. Le pouvoir promet une réponse, mais jamais gratuitement.'},{label:'Tester une version limitée et contrôlée',desc:'Un avantage immédiat, avec des conséquences possibles.',effect:{magic:-15,flags:{darkMagicStudied:true},reputation:{students:1},journal:'Tu as expérimenté une magie risquée dans des conditions limitées.'},next:'La magie fonctionne, mais laisse une sensation froide dans ta main. Tu as appris quelque chose — et créé une question que tu ne peux plus ignorer.'}]},
{title:'Le Patronus encore inachevé',place:'Un souvenir précieux',text:'La maîtrise ne vient pas en répétant une formule vide. Tu dois retrouver un souvenir qui ne soit pas seulement heureux, mais assez vrai pour te rappeler pourquoi tu continues lorsque la peur prend toute la place. Les années écoulées ont changé tes liens, tes certitudes et ta manière de regarder le monde.',choices:[{label:'Revenir à un souvenir de confiance partagée',desc:'La force peut venir d’un lien choisi.',effect:{patronusStage:1,magic:20,relations:{'Harry Potter':1},journal:'Tu as approfondi ton apprentissage du Patronus à travers un souvenir de confiance.'},next:'Une lumière argentée prend forme pendant une seconde de plus qu’avant. Tu ne distingues pas encore sa silhouette, mais elle n’est plus un simple éclat.'},{label:'Penser à un moment où tu as tenu bon seul',desc:'La persévérance est aussi une forme de courage.',effect:{patronusStage:1,magic:20,skills:{Défense:1},journal:'Tu as utilisé un souvenir de persévérance pour renforcer ta magie.'},next:'La lueur devient plus stable. Tu comprends que ton Patronus sera lié à ce que tu as traversé, pas à une étiquette que l’on t’a donnée.'}]}
],
[{title:'Les choix laissent des traces',place:'Poudlard',text:'Les années d’étude ont transformé l’école et ceux qui y vivent. Certaines personnes se souviennent de tes promesses ; d’autres, de tes silences. Une nouvelle menace oblige les élèves à choisir comment ils veulent agir ensemble. Les réponses faciles ont disparu depuis longtemps.',choices:[{label:'Protéger les autres en partageant les informations utiles',desc:'La confiance devient une ressource collective.',effect:{reputation:{students:2,house:2},housePoints:10,journal:'Tu as choisi de partager les informations nécessaires pour protéger les autres.'},next:'Des élèves qui se méfiaient hier acceptent aujourd’hui de coopérer. Tout le monde ne te suit pas, mais personne ne peut nier ton engagement.'},{label:'Garder certaines informations secrètes pour éviter la panique',desc:'La protection peut aussi exiger du discernement.',effect:{flags:{keptSecret:true},reputation:{students:-1},journal:'Tu as gardé certaines informations confidentielles pour éviter la panique.'},next:'Tu limites les rumeurs, mais quelques personnes se sentent écartées. Il faudra expliquer tes raisons avant que le silence ne devienne une fracture.'}]},
{title:'La veille du dernier chapitre',place:'Tour de Poudlard',text:'Le château est calme, mais ce calme n’a rien de paisible. Tu relis les notes accumulées, les noms, les promesses et les erreurs. Il n’existe pas de voie parfaite : seulement des choix dont tu dois assumer la portée, avec les personnes qui ont décidé de rester à tes côtés.',choices:[{label:'Préparer un plan avec tes alliés',desc:'La stratégie et la confiance se complètent.',effect:{reputation:{students:1},journal:'Tu as préparé la suite avec les personnes qui t’accordent leur confiance.'},next:'Le plan comporte des risques, mais chacun sait pourquoi il est là. Tu n’es plus l’élève arrivé au château avec une simple lettre.'},{label:'Prendre un moment seul pour clarifier tes priorités',desc:'Le silence peut aider à voir ce qui compte.',effect:{magic:20,health:10,journal:'Tu as pris le temps de clarifier tes priorités avant la dernière étape.'},next:'Le vent traverse les arches. Pour la première fois depuis longtemps, tu sais quelle promesse tu ne veux pas trahir.'}]}
],
[{title:'La rentrée des dernières promesses',place:'Grande Salle',text:'La Grande Salle te paraît à la fois familière et différente. Tu reconnais les détails que tu ne remarquais pas la première année : les regards échangés, les silences après une annonce, les habitudes qui disent davantage que les discours. Tu entres dans cette dernière année avec des liens déjà éprouvés et des questions qui ne peuvent plus attendre.',choices:[{label:'Réunir tes proches et comparer ce que chacun sait',desc:'Mettre les informations en commun avant d’agir.',effect:{reputation:{students:1},relations:{'Harry Potter':1,'Ron Weasley':1,'Hermione Granger':1},journal:'Tu as commencé ta dernière année en réunissant tes alliés.'},next:'Les versions ne concordent pas toujours, mais les désaccords deviennent visibles. Vous pouvez désormais distinguer les faits des suppositions et préparer une piste commune.'},{label:'Commencer par vérifier seul les indices les plus fragiles',desc:'La prudence protège les autres d’une fausse piste.',effect:{skills:{Défense:1},clue:'Un indice ancien reste valide, mais son interprétation doit changer.',journal:'Tu as vérifié les indices fragiles avant de les partager.'},next:'Tu découvres qu’un indice était exact, mais mal interprété. Cette correction évite une accusation inutile et donne un nouveau sens à un ancien événement.'}]},
{title:'La dernière leçon',place:'Salle de classe',text:'Le cours n’est pas une simple révision. Le professeur te demande de résoudre un problème en mobilisant ce que tu as appris, sans te donner la formule à suivre. Tu peux appliquer une méthode connue, ou combiner plusieurs compétences et accepter le risque de te tromper.',choices:[{label:'Appliquer une méthode éprouvée avec précision',desc:'La maîtrise consiste aussi à savoir quand ne pas improviser.',effect:{skills:{Sortilèges:1,Défense:1},housePoints:3,journal:'Tu as appliqué une méthode maîtrisée lors de ta dernière leçon.'},next:'Le résultat est stable. Tu comprends que les années d’apprentissage ne t’ont pas donné toutes les réponses : elles t’ont appris à reconnaître les bonnes questions.'},{label:'Combiner plusieurs sorts et adapter ton approche',desc:'La créativité peut ouvrir une solution nouvelle.',effect:{skills:{Sortilèges:2},magic:-5,flags:{creativeMagic:true},journal:'Tu as combiné plusieurs compétences lors de ta dernière leçon.'},next:'Le premier essai échoue, mais tu ajustes le geste et trouves une solution inattendue. Le professeur souligne ton inventivité autant que ta capacité à corriger tes erreurs.'}]}
]
];
// Chapitres supplémentaires : chaque année propose désormais plusieurs scènes et décisions jouables.
YEARS[0].push(
{title:'Le premier cours de sortilèges',place:'Salle de classe',text:'La salle sent la craie, le bois ciré et la pluie sur les capes. Les plumes attendent en rang devant les élèves. L’exercice semble simple, mais tu comprends vite que la précision compte autant que la volonté. À quelques tables de là, un élève retient son souffle devant un objet qui refuse de bouger.',choices:[{label:'Prendre le temps de maîtriser le mouvement',desc:'Une technique solide vaut mieux qu’un succès précipité.',effect:{skills:{Sortilèges:1},magic:5,housePoints:2,journal:'Tu as choisi la patience lors de ton premier cours de sortilèges.'},next:'Le petit objet tremble, glisse, puis s’élève de quelques centimètres. Le professeur remarque ton sérieux et t’encourage à poursuivre.'},{label:'Aider ton voisin avant de terminer ton exercice',desc:'L’entraide peut compter davantage qu’une démonstration.',effect:{relations:{'Hermione Granger':1,'Ron Weasley':1},reputation:{students:1},journal:'Tu as aidé un camarade pendant ton premier cours.'},next:'Vous reprenez les gestes ensemble. Votre résultat n’est pas parfait, mais le soulagement partagé vaut bien quelques secondes perdues.'}]},
{title:'La nuit derrière le portrait',place:'Couloir de la tour',text:'Le château a changé de visage après le couvre-feu. Les flammes des torches découpent des ombres sur les tapisseries, et un portrait somnolent marmonne qu’il n’a pas été peint pour surveiller des élèves. Tu entends un bruit métallique derrière une tenture. Il pourrait s’agir d’un objet tombé… ou d’un passage qu’on a voulu oublier.',choices:[{label:'Examiner la tenture avec Lumos',desc:'Utiliser un sort appris pour observer sans toucher.',effect:{magic:-3,clue:'Une charnière ancienne est dissimulée derrière la tenture.',flags:{hingeFound:true},journal:'Tu as découvert une charnière cachée derrière une tenture.'},next:'La lumière révèle une charnière incrustée dans la pierre. Tu n’ouvres pas le passage, mais tu sais désormais qu’il existe.'},{label:'Réveiller le portrait et lui poser des questions',desc:'Un témoin bavard peut connaître l’histoire du lieu.',effect:{reputation:{students:1},relations:{'Neville Londubat':1},journal:'Tu as interrogé un portrait plutôt que de forcer un passage.'},next:'Le portrait proteste, puis se met à raconter une histoire décousue. Au milieu de ses digressions, un nom revient deux fois : celui d’un ancien gardien des couloirs.'}]},
{title:'La première lettre de Noël',place:'Salle commune',text:'Les fenêtres se couvrent de givre. Une lettre venue de chez toi t’attend près du feu, avec une petite attention soigneusement emballée. En la lisant, tu ressens le décalage entre la vie que tu connaissais et celle qui prend forme ici. Tu peux partager ce moment, ou le garder pour toi.',choices:[{label:'Lire la lettre à voix haute à tes proches de Poudlard',desc:'Faire une place à ton passé dans tes nouvelles amitiés.',effect:{relations:{'Ron Weasley':1,'Harry Potter':1},flags:{sharedChristmasLetter:true},journal:'Tu as partagé une lettre importante pendant les vacances de Noël.'},next:'Les questions viennent avec délicatesse. Pour la première fois, ton histoire familiale ne semble plus si éloignée de ta vie au château.'},{label:'Répondre en privé et conserver l’enveloppe',desc:'Protéger un lien intime sans t’isoler des autres.',effect:{galleons:2,flags:{privateChristmasLetter:true},journal:'Tu as pris un moment privé pour répondre à ta famille.'},next:'Tu choisis tes mots avec soin. La réponse sera peut-être courte, mais elle dit ce que tu n’arrives pas encore à expliquer en personne.'}]}
);
YEARS[1].push(
{title:'La rumeur au petit-déjeuner',place:'Grande Salle',text:'Une rumeur circule de table en table : quelqu’un aurait vu une lumière sous une porte condamnée. Les versions divergent déjà. Certains veulent prévenir un professeur, d’autres préfèrent enquêter avant que l’histoire ne soit déformée. Tu reconnais un détail qui ressemble à une note de ton journal.',choices:[{label:'Vérifier les témoignages séparément',desc:'Comparer les détails avant de tirer une conclusion.',effect:{skills:{Défense:1},clue:'Trois témoins décrivent la même lumière, mais à des heures différentes.',journal:'Tu as comparé les témoignages autour de la rumeur.'},next:'Les récits ne concordent pas sur l’heure, mais tous évoquent une odeur de poussière froide. La piste devient plus précise sans encore livrer son explication.'},{label:'Prévenir un professeur de confiance',desc:'La prudence peut éviter qu’un élève se mette en danger.',effect:{reputation:{professors:1},housePoints:2,journal:'Tu as choisi de signaler une rumeur inquiétante.'},next:'Le professeur te remercie sans dramatiser. Il promet de vérifier le lieu et te demande de ne pas y aller seul.'}]},
{title:'Le devoir qui résiste',place:'Bibliothèque',text:'Un devoir de potions demande d’expliquer pourquoi une préparation peut échouer malgré des ingrédients corrects. Tes notes contiennent deux explications contradictoires. Une camarade te propose ses propres observations, mais elle a tendance à conclure trop vite. Le travail exige de distinguer ce que vous savez de ce que vous supposez.',choices:[{label:'Reprendre les étapes une à une',desc:'La méthode fait progresser tes connaissances.',effect:{skills:{Potions:2},reputation:{professors:1},housePoints:3,journal:'Tu as repris méthodiquement les étapes d’un devoir de potions.'},next:'Tu découvres que l’ordre d’ajout importe autant que la quantité. La réponse devient plus claire dès que tu sépares les faits des hypothèses.'},{label:'Confronter tes notes à celles d’un camarade',desc:'Le travail collectif révèle les angles morts.',effect:{relations:{'Hermione Granger':1},skills:{Potions:1},journal:'Tu as confronté tes notes à celles d’un camarade.'},next:'Vos notes ne disent pas la même chose, mais leur comparaison révèle l’étape oubliée. Vous corrigez le devoir sans prétendre avoir tout compris.'}]},
{title:'Une sortie qui se mérite',place:'Pré-au-Lard',text:'Les élèves parlent de vitrines, de boissons chaudes et de boutiques aux étagères pleines d’objets étranges. La sortie dépend des règles de l’école et des autorisations nécessaires. Tu peux préparer ton trajet avec sérieux ou chercher à suivre un groupe sans vérifier les conditions.',choices:[{label:'Vérifier les règles et préparer ta sortie',desc:'Une occasion bien préparée laisse plus de place à la découverte.',effect:{galleons:-2,reputation:{professors:1},flags:{hogsmeadeReady:true},journal:'Tu as préparé soigneusement une sortie à Pré-au-Lard.'},next:'Tu arrives sans précipitation et peux profiter des boutiques. Un marchand te montre un petit objet gravé dont le symbole ressemble à un indice déjà rencontré.'},{label:'Suivre tes amis et improviser',desc:'L’improvisation peut rapprocher, mais comporte des risques.',effect:{relations:{'Ron Weasley':1},reputation:{professors:-1},journal:'Tu as suivi tes amis sans tout planifier.'},next:'La sortie reste agréable, mais vous devez faire un détour après avoir mal compris une consigne. Tu retiens qu’une bonne aventure demande aussi un peu de préparation.'}]}
);
YEARS[2].push(
{title:'Les archives sous la poussière',place:'Bibliothèque',text:'Un registre relié de toile s’ouvre à une page marquée par une tache d’encre. Plusieurs noms ont été rayés, mais les dates restent lisibles. Tu peux chercher une correspondance avec tes indices, ou demander à une personne de confiance de t’aider à lire les annotations anciennes.',choices:[{label:'Comparer les dates et les plans',desc:'Faire parler les documents entre eux.',effect:{skills:{Sortilèges:1},clue:'Les archives signalent une salle déplacée après des travaux anciens.',flags:{archiveMatched:true},journal:'Tu as rapproché les archives des plans de Poudlard.'},next:'Les dates montrent qu’une pièce a été déplacée dans les registres, sans qu’aucune salle ne soit officiellement supprimée. Le mystère concerne peut-être moins une porte qu’un souvenir effacé.'},{label:'Demander l’aide d’un ami attentif',desc:'Un autre regard peut remarquer ce qui t’échappe.',effect:{relations:{'Hermione Granger':1,'Harry Potter':1},clue:'Une annotation utilise un symbole déjà vu près du lac.',journal:'Tu as partagé une recherche d’archives avec un ami.'},next:'Ton ami remarque un petit symbole dans la marge. Il ressemble à celui que tu as aperçu près du lac : les indices commencent enfin à se répondre.'}]},
{title:'La créature dans la serre',place:'Serres',text:'Un bruit discret vient d’une caisse entrouverte. À l’intérieur, une petite créature magique s’est cachée sous des feuilles froissées. Elle ne semble pas agressive, mais sa respiration rapide trahit sa peur. Tu as quelques instants pour choisir comment l’approcher.',choices:[{label:'Rester immobile et observer son comportement',desc:'Comprendre avant d’agir.',effect:{skills:{Potions:1},flags:{creatureTrusted:true},inventoryAdd:'Feuille argentée',journal:'Tu as gagné la confiance d’une petite créature en respectant son espace.'},next:'Après un long moment, la créature s’approche d’elle-même. Elle laisse tomber une feuille argentée, utile pour certaines préparations, puis retourne se cacher.'},{label:'Appeler la personne responsable des serres',desc:'Protéger la créature avec l’aide d’un adulte.',effect:{reputation:{professors:1},housePoints:2,journal:'Tu as demandé de l’aide pour protéger une créature magique.'},next:'La personne responsable arrive rapidement et te remercie de ne pas avoir tenté de la saisir. Tu apprends comment reconnaître ses signes de stress.'}]},
{title:'Un souvenir qui prend forme',place:'Tour silencieuse',text:'Tu repenses aux moments qui t’ont aidé à continuer : une main tendue, une promesse tenue, ou une décision difficile prise sans témoin. Le sortilège que tu étudies ne répond pas à une formule récitée mécaniquement. Il exige de comprendre ce que ce souvenir signifie pour toi, aujourd’hui.',choices:[{label:'Revivre un moment de confiance',desc:'Le lien choisi devient une ancre.',effect:{patronusStage:1,magic:15,journal:'Tu as approfondi le travail intérieur nécessaire au Patronus.'},next:'La lueur argentée se rassemble au creux de ta baguette. Elle tient plus longtemps, comme si le souvenir avait enfin trouvé sa place.'},{label:'Accepter une peur sans la laisser décider',desc:'Le courage n’efface pas la peur : il permet d’avancer.',effect:{patronusStage:1,skills:{Défense:1},journal:'Tu as travaillé le Patronus en faisant face à une peur réelle.'},next:'La lumière ne prend pas encore de forme, mais elle ne s’éteint pas. Tu comprends que la maîtrise commence parfois par le fait de rester présent.'}]}
);
YEARS[3].push(
{title:'Le témoignage contradictoire',place:'Couloir des portraits',text:'Deux élèves racontent le même incident avec des détails incompatibles. L’un paraît sincère, l’autre nerveux ; aucun de ces signes ne prouve quoi que ce soit. Le carnet d’enquête contient trois indices, mais il manque une pièce pour comprendre ce qui s’est réellement passé.',choices:[{label:'Reconstituer les déplacements et les horaires',desc:'Laisser les faits guider ton jugement.',effect:{skills:{Défense:1},clue:'Les horaires excluent l’un des témoignages sans prouver une intention.',reputation:{professors:1},journal:'Tu as reconstitué une chronologie avant de juger.'},next:'La chronologie élimine une partie de l’histoire, mais pas le doute. Tu peux corriger les faits sans inventer les intentions des personnes impliquées.'},{label:'Parler séparément aux deux élèves',desc:'Donner à chacun la possibilité d’expliquer ses raisons.',effect:{relations:{'Neville Londubat':1},clue:'Un témoin a omis un détail par peur des conséquences.',journal:'Tu as recueilli deux témoignages séparés.'},next:'L’un des élèves reconnaît avoir tu un détail par peur d’être puni. Le détail ne résout pas tout, mais il change le sens de plusieurs indices.'}]},
{title:'La potion imparfaite',place:'Donjons',text:'Une préparation prend une teinte trop sombre et une odeur métallique s’élève du chaudron. Rien n’a explosé, mais le résultat n’est pas celui attendu. Tu peux tenter une correction, au risque de gâcher les ingrédients, ou arrêter le processus et consigner l’erreur pour comprendre ce qui s’est passé.',choices:[{label:'Corriger prudemment la température et le mélange',desc:'Une intervention mesurée peut sauver la préparation.',effect:{skills:{Potions:2},magic:5,journal:'Tu as corrigé une potion imparfaite avec prudence.'},next:'La teinte s’éclaircit. La potion reste moins puissante que prévu, mais tu comprends comment la chaleur a modifié le mélange.'},{label:'Arrêter et documenter l’échec',desc:'Une erreur consignée devient un apprentissage.',effect:{skills:{Potions:1},inventoryAdd:'Notes de potion',reputation:{professors:1},journal:'Tu as choisi de documenter un échec de potion.'},next:'Tu notes chaque étape avant de vider le chaudron selon les règles. Le professeur apprécie que tu aies privilégié la sécurité à la fierté.'}]},
{title:'La Coupe se rapproche',place:'Terrain de Quidditch',text:'Les entraînements deviennent plus intenses et les rivalités plus visibles. Ton équipe ne manque pas de talent, mais la coordination se fissure lorsque chacun veut prouver sa valeur. Le prochain exercice peut renforcer la confiance ou exposer les faiblesses du groupe.',choices:[{label:'Organiser un entraînement centré sur les passes',desc:'La cohésion fait gagner du temps et des occasions.',effect:{quidditch:{trained:2},relations:{'Harry Potter':1},reputation:{students:1},journal:'Tu as favorisé la coordination lors de l’entraînement de Quidditch.'},next:'Les passes deviennent plus fluides. Vous n’êtes pas encore imbattables, mais l’équipe commence à jouer comme un ensemble plutôt que comme des individualités.'},{label:'Travailler ton propre point faible',desc:'La responsabilité commence par ce que tu peux améliorer.',effect:{quidditch:{trained:1},skills:{Défense:1},journal:'Tu as travaillé un point faible personnel au Quidditch.'},next:'Tu répètes le mouvement jusqu’à ce qu’il devienne plus naturel. L’équipe devra encore travailler sa cohésion, mais tu arrives au prochain entraînement mieux préparé.'}]}
);
YEARS[4].push(
{title:'La bibliothèque après la fermeture',place:'Bibliothèque',text:'Un document que tu avais consulté a été déplacé. Sur la table, un feuillet propre porte une phrase qui semble répondre à l’une de tes anciennes notes. Quelqu’un suit donc la même piste — ou cherche à te faire croire qu’il le fait.',choices:[{label:'Vérifier l’encre et la provenance du feuillet',desc:'Éviter le piège d’une réponse trop commode.',effect:{skills:{Sortilèges:1},clue:'Le feuillet est récent, mais son encre imite une écriture ancienne.',journal:'Tu as vérifié la provenance d’un indice suspect.'},next:'Le papier est récent. Son auteur connaît les archives, mais a reproduit certains détails de manière imparfaite. Tu as découvert une tentative d’influence plutôt qu’une réponse.'},{label:'Laisser une question et observer qui revient',desc:'Une contre-piste peut révéler une intention.',effect:{flags:{counterClue:true},reputation:{students:1},journal:'Tu as laissé une contre-piste pour observer les réactions.'},next:'Le lendemain, la note a disparu et une marque a été laissée sur la table. Tu n’as pas identifié la personne, mais tu sais désormais que ta recherche est observée.'}]},
{title:'Une confiance mise à l’épreuve',place:'Salle commune',text:'Un ami découvre que tu lui as caché un élément important. Tu avais tes raisons, mais le résultat est le même : il se demande si tu lui fais réellement confiance. Tu peux tout expliquer, ou reconnaître que tu as choisi à sa place ce qu’il avait le droit de savoir.',choices:[{label:'Expliquer tes raisons et écouter sa réaction',desc:'La sincérité ne garantit pas le pardon, mais ouvre une porte.',effect:{relations:{'Harry Potter':1,'Hermione Granger':1},reputation:{students:1},journal:'Tu as expliqué une décision difficile à un ami.'},next:'La conversation est inconfortable. Ton ami n’accepte pas immédiatement tes raisons, mais il voit que tu es prêt à entendre ce que ton silence lui a coûté.'},{label:'Assumer le tort sans chercher à te justifier',desc:'Reconnaître l’impact de son choix.',effect:{relations:{'Harry Potter':2},flags:{ownedSecret:true},journal:'Tu as reconnu l’impact d’un secret sur une relation.'},next:'Tu ne peux pas effacer le silence, mais tu peux cesser de le défendre. La confiance demandera du temps et des actes répétés.'}]},
{title:'La tentation du raccourci',place:'Salle abandonnée',text:'La formule interdite que tu as étudiée pourrait résoudre un problème en quelques secondes. Les notes décrivent son efficacité, mais plusieurs témoignages mentionnent des effets secondaires : fatigue, méfiance, et une magie qui semble laisser une empreinte. Tu peux refuser de l’utiliser, ou accepter un avantage dont tu ne connais pas tout le prix.',choices:[{label:'Refuser le raccourci et chercher une autre solution',desc:'La lenteur protège parfois ce qui compte.',effect:{skills:{Défense:1},reputation:{professors:1},journal:'Tu as refusé un raccourci magique risqué.'},next:'La solution prend plus de temps, mais elle ne t’oblige pas à cacher ce que tu as fait. Tu gardes une marge de manœuvre pour la suite.'},{label:'Utiliser la formule dans une situation contrôlée',desc:'Un pouvoir immédiat crée une dette possible.',effect:{magic:-20,flags:{darkMagicUsed:true},reputation:{students:1,professors:-1},journal:'Tu as utilisé une formule risquée et accepté ses conséquences possibles.'},next:'La formule fonctionne. Une douleur froide traverse ton bras et ta baguette reste silencieuse un instant. Tu as obtenu un avantage, mais la décision pourra laisser une trace.'}]}
);
YEARS[5].push(
{title:'Les lettres qui ne sont jamais arrivées',place:'Tour des hiboux',text:'Plusieurs lettres semblent avoir été retardées ou redirigées. Il peut s’agir d’une erreur de tri, d’un oubli ou d’une intervention volontaire. Une enveloppe abîmée porte une marque que tu as déjà vue dans les archives. Le mystère touche désormais des personnes auxquelles tu tiens.',choices:[{label:'Comparer les dates et les registres d’envoi',desc:'Une méthode discrète pour distinguer l’erreur de l’intention.',effect:{clue:'Plusieurs courriers ont été retenus au même moment.',skills:{Sortilèges:1},journal:'Tu as examiné les registres des lettres retardées.'},next:'Les retards se concentrent sur une période précise. Cela ne prouve pas un complot, mais suffit pour justifier une enquête plus sérieuse.'},{label:'Prévenir les personnes concernées',desc:'Partager l’incertitude plutôt que laisser la méfiance grandir.',effect:{relations:{'Ron Weasley':1,'Hermione Granger':1},reputation:{students:1},journal:'Tu as prévenu tes proches au sujet des lettres manquantes.'},next:'Les réactions varient, mais personne ne se sent laissé dans l’ignorance. Vous pouvez désormais vérifier les faits ensemble.'}]},
{title:'Le Patronus révèle sa forme',place:'Une clairière protégée',text:'Tu as passé des années à apprendre que le souvenir ne vaut pas par sa perfection, mais par sa vérité. Les difficultés traversées, les personnes que tu as choisies de protéger et les moments où tu as accepté tes propres limites se rassemblent. Tu inspires, lèves ta baguette et laisses le souvenir exister sans chercher à le contrôler.',choices:[{label:'Laisser le souvenir venir sans le forcer',desc:'Faire confiance à ce que ton parcours a construit.',condition:'patronus',effect:{patronusStage:1,magic:25,journal:'Tu as franchi une étape décisive dans l’apprentissage du Patronus.'},next:'La lumière argentée s’échappe de ta baguette, puis se rassemble. Une silhouette prend forme, unique à ton histoire. Tu n’as pas choisi un emblème : tu as découvert ce qui répondait en toi.'},{label:'Recommencer après avoir retrouvé ton calme',desc:'La maîtrise peut demander une dernière respiration.',effect:{patronusStage:1,magic:20,health:5,journal:'Tu as poursuivi l’apprentissage du Patronus avec patience.'},next:'La première tentative s’éteint, mais la seconde tient. Une silhouette argentée apparaît et se tourne vers toi comme si elle reconnaissait le chemin parcouru.'}]},
{title:'Le plan des alliés',place:'Salle commune',text:'Les informations sont enfin assez nombreuses pour préparer une action, mais pas assez pour garantir le succès. Chacun a une compétence, une peur et une raison de rester. Tu dois décider si tu confies des tâches à un petit groupe ou si tu partages les éléments essentiels avec tous ceux qui sont prêts à aider.',choices:[{label:'Répartir les tâches selon les forces de chacun',desc:'La confiance se traduit par des responsabilités concrètes.',effect:{reputation:{students:2,house:2},housePoints:5,flags:{alliesPlan:true},journal:'Tu as organisé un plan en tenant compte des forces de tes alliés.'},next:'Le plan n’efface pas les risques, mais chacun sait ce qu’il doit faire. Les personnes qui t’accompagnent se sentent considérées, pas simplement utilisées.'},{label:'Garder une équipe réduite et mobile',desc:'Moins de personnes, moins de risques de fuite.',effect:{flags:{smallTeam:true},skills:{Défense:1},journal:'Tu as choisi une équipe réduite pour une opération délicate.'},next:'Vous gagnez en discrétion, au prix d’une charge plus lourde pour chaque personne. La stratégie est possible, mais il faudra rester attentif aux limites de chacun.'}]}
);
YEARS[6].push(
{title:'Les portes que tu as ouvertes',place:'Poudlard',text:'Les anciens indices ne sont plus de simples curiosités. Plusieurs pistes se rejoignent dans les couloirs, les archives et les souvenirs de personnes que tu as rencontrées. Une décision prise en première année a peut-être rendu cette étape plus facile — ou plus douloureuse. Tu dois choisir ce que tu fais de ce que tu sais.',choices:[{label:'Partager les preuves avec tes alliés de confiance',desc:'Une vérité vérifiable vaut mieux qu’un secret isolé.',effect:{reputation:{students:2,professors:1},housePoints:5,journal:'Tu as partagé les preuves accumulées au fil des années.'},next:'Les pièces du dossier sont désormais accessibles à ceux qui peuvent les vérifier. Les désaccords demeurent, mais la discussion repose enfin sur des faits communs.'},{label:'Conserver une dernière piste confidentielle',desc:'Protéger une source, au risque de créer de la distance.',effect:{flags:{finalLeadSecret:true},relations:{'Hermione Granger':-1},journal:'Tu as gardé une piste confidentielle avant la dernière étape.'},next:'Tu protèges une source fragile, mais ton silence inquiète un allié. Il faudra assumer cette distance lorsque le moment de décider arrivera.'}]},
{title:'La dernière préparation',place:'Salle de classe abandonnée',text:'La nuit approche et le château semble retenir son souffle. Tu vérifies ta baguette, les objets que tu as conservés et les promesses que tu n’as pas oubliées. Il n’existe pas de préparation parfaite : seulement des choix qui augmentent tes chances et des personnes qui savent pourquoi elles restent.',choices:[{label:'Préparer les protections et vérifier les ressources',desc:'La préparation peut limiter les risques.',effect:{health:15,magic:25,inventoryAdd:'Trousse de préparation',skills:{Défense:1},journal:'Tu as préparé tes ressources avant la confrontation finale.'},next:'Tu vérifies chaque objet, chaque sort et chaque issue possible. La peur reste présente, mais elle ne décide plus à ta place.'},{label:'Prendre le temps de parler à tes proches',desc:'Les liens sont aussi une forme de préparation.',effect:{relations:{'Harry Potter':1,'Ron Weasley':1,'Hermione Granger':1},reputation:{students:1},journal:'Tu as pris un dernier moment avec tes proches avant la confrontation.'},next:'Les mots sont simples, parfois maladroits. Personne ne promet que tout ira bien ; vous vous promettez seulement de ne pas oublier pourquoi vous êtes là.'}]},
{title:'La dernière page',place:'Le cœur du château',text:'Tout ce que tu as appris se rassemble dans cet instant. Les indices, les sorts maîtrisés, les amitiés entretenues et les erreurs assumées ne garantissent pas la victoire, mais ils déterminent les options qui s’offrent à toi. Le château n’attend pas un héros parfait. Il attend que tu choisisses comment agir.',choices:[{label:'Avancer avec tes alliés et protéger ceux qui sont vulnérables',desc:'La force se mesure aussi à ce que l’on refuse d’abandonner.',effect:{health:10,magic:15,reputation:{students:2,house:2},housePoints:10,flags:{finalChoice:'protect'},journal:'Dans le dernier chapitre, tu as choisi d’avancer avec tes alliés.'},next:'Tu avances avec les personnes qui ont choisi de rester. Les décisions anciennes se font sentir : certaines portes s’ouvrent, d’autres demeurent fermées. Mais cette fois, tu sais pourquoi tu avances.'},{label:'Suivre seul la piste la plus risquée',desc:'Une décision courageuse, mais qui peut coûter cher.',effect:{health:-10,magic:20,flags:{finalChoice:'alone'},journal:'Tu as choisi de suivre seul la piste la plus risquée.'},next:'Tu prends le passage étroit. La solitude te donne de la vitesse, mais t’oblige à porter chaque risque sans relais. Tu n’es plus l’élève du premier jour : tu sais ce que cette décision peut coûter.'}]}
);

// Activités interactives complémentaires : duel tactique, cours, potion, créature et Quidditch.
function activitiesPage(){
 const canDuel=S.started;
 return `${shellTitle('Pratique et aventures','Activités <em>de Poudlard</em>','Des systèmes jouables en complément de l’histoire : entraîne-toi, expérimente et accepte les conséquences de tes décisions.')}
 <div class="content wide"><div class="grid2">
 <div class="card"><div class="eyebrow">Défense magique</div><h2>Entraînement au duel</h2><p class="muted small">Choisis une action tactique. Tes sorts connus, ton énergie et ta maîtrise influencent le résultat.</p>${S.duel?.active?`<p>Adversaire : ${esc(S.duel.enemy)} · Résistance : ${S.duel.enemyHP}%</p><div class="btnrow">${S.spells.filter(x=>['Expelliarmus','Stupefix','Accio','Lumos'].includes(x)).map(x=>`<button class="btn" onclick="duelAction('${x}')">${x}</button>`).join('')}<button class="btn" onclick="duelAction('protego')">Protego</button><button class="btn" onclick="duelAction('esquive')">Esquiver</button><button class="btn" onclick="duelAction('repos')">Reprendre son souffle</button></div>`:`<div class="btnrow"><button class="btn primary" onclick="startDuel()">Commencer un duel d’entraînement</button></div>`}<p class="small muted">État : ${S.duel?.active?'duel en cours':'aucun duel en cours'}</p></div>
 <div class="card"><div class="eyebrow">Salle de classe</div><h2>Réviser une matière</h2><p class="muted small">Choisis une discipline pour progresser par l’exercice plutôt que par des niveaux artificiels.</p><div class="btnrow">${['Sortilèges','Potions','Défense','Métamorphose'].map(x=>`<button class="btn" onclick="study('${x}')">${x}</button>`).join('')}</div></div>
 <div class="card"><div class="eyebrow">Laboratoire</div><h2>Préparer une potion</h2><p class="muted small">Choisis une recette, puis réalise trois étapes. La précision et la matière étudiée influencent le résultat.</p>${S.potionLab?.active?`<p><strong>${esc(S.potionLab.name)}</strong> · Étape ${S.potionLab.step+1}/3</p><p class="muted small">${esc(['Préparer les ingrédients et mesurer les quantités.','Régler la chaleur et mélanger dans le bon ordre.','Stabiliser la préparation et vérifier sa couleur.'][S.potionLab.step]||'Terminer la préparation.')}</p><div class="btnrow"><button class="btn" onclick="potionStep('precis')">Suivre la recette</button><button class="btn" onclick="potionStep('intuitif')">Improviser avec prudence</button><button class="btn" onclick="cancelPotion()">Abandonner</button></div>`:`<div class="btnrow"><button class="btn" onclick="beginPotion('soin')">Potion de soin · 3 gallions</button><button class="btn" onclick="beginPotion('concentration')">Potion de concentration · 2 gallions</button><button class="btn" onclick="beginPotion('protection')">Potion de protection · 4 gallions</button></div>`}</div>
 <div class="card"><div class="eyebrow">Terrain de Quidditch</div><h2>Match tactique</h2><p class="muted small">Un match court où tes décisions de passe, de protection et d’attaque influencent le score.</p>${S.quidditch.joined?`<p class="pill">Membre de l’équipe · Poste : ${esc(S.quidditch.position||'remplaçant')}</p><div class="btnrow"><button class="btn primary" onclick="playQuidditch('passe')">Construire une action</button><button class="btn" onclick="playQuidditch('attaque')">Tenter une attaque</button><button class="btn" onclick="playQuidditch('proteger')">Protéger un coéquipier</button></div>`:`<p class="muted small">Les premières années peuvent s’entraîner, mais l’accès à l’équipe dépend de l’âge et de l’expérience.</p><div class="btnrow"><button class="btn primary" onclick="quidditchTryout()">Demander un essai</button><button class="btn" onclick="playQuidditch('passe')">S’entraîner librement</button></div>`}<p class="muted small">Entraînements : ${S.quidditch.trained||0} · Victoires : ${S.quidditch.wins||0} · Réputation sportive : ${S.reputation.students}</p></div>
 <div class="card"><div class="eyebrow">Soins aux créatures</div><h2>Rencontre magique</h2><p class="muted small">Observe les signes, consulte tes connaissances et choisis une approche adaptée. La confiance se gagne, elle ne se force pas.</p><div class="btnrow"><button class="btn" onclick="creatureEncounter('observer')">Observer à distance</button><button class="btn" onclick="creatureEncounter('nourrir')">Offrir un ingrédient</button><button class="btn" onclick="creatureEncounter('approcher')">Approcher doucement</button></div></div>
 <div class="card"><div class="eyebrow">Évaluation scolaire</div><h2>Examen de fin de trimestre</h2><p class="muted small">Réponds à une épreuve de méthode. Tes compétences acquises influencent la note et les points de maison.</p><div class="btnrow"><button class="btn primary" onclick="takeExam('Sortilèges')">Sortilèges</button><button class="btn" onclick="takeExam('Potions')">Potions</button><button class="btn" onclick="takeExam('Défense')">Défense</button><button class="btn" onclick="takeExam('Métamorphose')">Métamorphose</button></div></div>
 <div class="card"><div class="eyebrow">Enquête et déduction</div><h2>Tableau des indices</h2><p class="muted small">Compare les pistes réunies, choisis une méthode et consigne une conclusion. La chronique garde la trace de tes hypothèses.</p><div class="btnrow"><button class="btn primary" onclick="investigate()">Examiner les indices (${S.clues.length})</button></div></div>
 <div class="card"><div class="eyebrow">Choix difficiles</div><h2>Étudier une magie risquée</h2><p class="muted small">Comprendre un pouvoir ne t’oblige pas à l’utiliser. Cette décision peut modifier ta réputation et la manière dont tes proches te font confiance.</p><div class="btnrow"><button class="btn" onclick="studyDarkMagic(false)">Étudier les risques sans l’utiliser</button><button class="btn" onclick="studyDarkMagic(true)">Tenter la formule</button></div><p class="muted small">${S.flags.darkMagicUsed?'Tu as déjà utilisé cette magie et ses conséquences restent dans ta chronique.':S.flags.darkMagicStudied?'Tu as déjà étudié cette magie sans forcément l’utiliser.':'Aucune décision prise pour le moment.'}</p></div>
 <div class="card"><div class="eyebrow">Liens personnels</div><h2>Prendre des nouvelles</h2><p class="muted small">Choisis une personne à retrouver. Les réactions dépendent de votre relation actuelle et des événements déjà vécus.</p><div class="btnrow">${Object.keys(S.relations).map(n=>`<button class="btn" onclick="socialVisit('${n.replace(/'/g, "\'")}')">Parler à ${esc(n.split(' ')[0])}</button>`).join('')}</div></div>
 <div class="card"><div class="eyebrow">Ton compagnon</div><h2>${esc(S.character.animal||'Animal à choisir')}</h2><p class="muted small">Ton compagnon peut apparaître dans les scènes et attirer ton attention sur un détail, sans jamais être indispensable à une quête.</p><div class="btnrow"><button class="btn" onclick="spendTimeWithPet()">Passer un moment ensemble</button></div></div>
 <div class="card"><div class="eyebrow">Comptoir magique</div><h2>Petits achats utiles</h2><p class="muted small">Utilise tes gallions pour obtenir un objet ou un ingrédient. Les achats sont facultatifs et ne bloquent jamais le scénario principal.</p><div class="btnrow"><button class="btn" onclick="shopBuy('Ingrédients de potion',3)">Ingrédients · 3</button><button class="btn" onclick="shopBuy('Carnet d’enquête',4)">Carnet d’enquête · 4</button><button class="btn" onclick="shopBuy('Friandise pour créature',2)">Friandise · 2</button><button class="btn" onclick="shopBuy('Livre de révision',5)">Livre de révision · 5</button></div></div>
 <div class="card"><div class="eyebrow">Calendrier vivant</div><h2>Temps libre</h2><p class="muted small">Tes activités font avancer la journée narrative, avec des effets sur l’énergie et les relations. Aucun simulateur minute par minute.</p><div class="btnrow"><button class="btn" onclick="freeTime('friends')">Retrouver des amis</button><button class="btn" onclick="freeTime('study')">Étudier au calme</button><button class="btn" onclick="freeTime('rest')">Se reposer</button></div></div>
 </div><div class="card"><div class="eyebrow">Défi de ta maison</div><h2>${esc(S.character.house||'Poudlard')} : une occasion exclusive</h2><p class="muted small">Chaque maison valorise une approche différente. Ce défi ne remplace pas l’histoire principale et peut être relevé une fois par année.</p><div class="btnrow"><button class="btn primary" onclick="houseChallenge()">Relever le défi de maison</button></div></div><div class="card"><div class="eyebrow">Quêtes personnelles</div><h2>Ton tableau d’objectifs</h2>${S.quests.length?S.quests.map((q,i)=>`<div class="listrow"><div class="listicon">✧</div><div style="flex:1"><strong>${esc(typeof q==='string'?q:q.title)}</strong><p>${esc(typeof q==='string'?'Une piste à poursuivre au fil de ton aventure.':q.description||'Une occasion à saisir selon tes choix.')}</p>${typeof q==='object'&&!q.completed?`<button class="btn" onclick="completeQuest(${i})">Consigner comme accomplie</button>`:typeof q==='object'&&q.completed?'<span class="pill">Accomplie</span>':''}</div></div>`).join(''):'<p class="muted">Aucune quête personnelle n’a encore été inscrite. Les objectifs apparaîtront au fil des découvertes.</p>'}</div></div>`;
}
function houseChallenge(){if(!S.started)return toast('Commence ton aventure pour relever un défi.');const key=`houseChallenge_${S.year}`;if(S.flags[key])return toast('Tu as déjà relevé le défi de ta maison cette année.');const house=S.character.house;let title='',text='',effect={};if(house==='Gryffondor'){title='Le courage avec discernement';text='Un camarade s’apprête à franchir seul un passage dangereux pour prouver sa bravoure. Tu peux le suivre sans réfléchir ou trouver une manière plus sûre d’avancer.';effect={relations:{'Neville Londubat':1},skills:{Défense:1},housePoints:4,journal:'Tu as relevé le défi de Gryffondor en associant courage et prudence.'}}else if(house==='Serpentard'){title='La stratégie et ses limites';text='Deux élèves veulent obtenir la même information. Tu peux manipuler leurs rivalités ou organiser un échange où chacun comprend ce qu’il accepte.';effect={skills:{Sortilèges:1},galleons:2,reputation:{students:1},housePoints:4,journal:'Tu as relevé le défi de Serpentard sans renoncer à tes limites.'}}else if(house==='Serdaigle'){title='L’énigme des marges';text='Une suite de symboles semble décrire un lieu, mais une ligne ne correspond pas au reste. Tu dois comparer les motifs plutôt que deviner le mot final.';effect={skills:{Sortilèges:1,Métamorphose:1},clue:'Les symboles des marges décrivent une direction plutôt qu’un nom de lieu.',housePoints:4,journal:'Tu as résolu une partie de l’énigme proposée à Serdaigle.'}}else{title='L’aide qui ne se voit pas';text='Un groupe a besoin d’aide pour préparer un événement, mais les tâches les moins visibles risquent d’être oubliées. Tu peux répartir le travail et vérifier que personne ne reste seul avec tout l’effort.';effect={relations:{'Ron Weasley':1,'Hermione Granger':1},reputation:{students:2},housePoints:4,journal:'Tu as relevé le défi de Poufsouffle en répartissant les efforts avec équité.'}}S.flags[key]=true;applyEffect(effect);S.quests.push({title:`Défi de ${house} — ${title}`,description:'Défi de maison accompli : ses effets sont conservés dans ta chronique.',completed:true});autoSave();render();showModal(title,text+`<br><br><strong>Défi accompli :</strong> +4 points pour ta maison.`,()=>render())}
function completeQuest(i){const q=S.quests[i];if(!q||typeof q!=='object'||q.completed)return;if(!q.title||!q.description){toast('Cette entrée est une piste narrative, pas une quête validable depuis ce menu.');return}q.completed=true;S.journal.push(`Année ${S.year} — Quête accomplie : ${q.title}.`);S.reputation.house=Math.min(10,S.reputation.house+1);S.housePoints+=1;S.houseCup+=1;autoSave();render();toast('Quête consignée : +1 point de maison.')}
function takeExam(subject){if(!S.started)return toast('Crée ton personnage avant les examens.');const skill=S.skills[subject]||0;const prep=(S.flags['exam_'+S.year+'_'+subject]||false);if(prep)return toast('Tu as déjà passé cette épreuve cette année.');const score=Math.min(20,8+skill*2+(S.reputation.professors>2?2:0)+(S.year>2?1:0));S.flags['exam_'+S.year+'_'+subject]=true;S.flags['grade_'+S.year+'_'+subject]=score;S.journal.push(`Année ${S.year} — Examen de ${subject} : ${score}/20.`);if(score>=16){S.housePoints+=5;S.houseCup+=5;S.reputation.professors=Math.min(10,S.reputation.professors+1)}else if(score>=12){S.housePoints+=2;S.houseCup+=2}else{S.journal.push(`Tu as noté les points à retravailler en ${subject} avant la prochaine évaluation.`)}autoSave();render();showModal(`Examen de ${subject}`,`Résultat : <strong>${score}/20</strong>.<br><br>${score>=16?'Excellent travail : tu gagnes 5 points pour ta maison et la confiance du professeur.':score>=12?'Un résultat solide : tu gagnes 2 points de maison et identifies les notions à consolider.':'Cette note montre surtout ce qu’il te reste à travailler. La progression continue : aucun examen ne bloque l’histoire.'}`,()=>render())}
function investigate(){if(!S.started)return toast('Commence ton aventure pour enquêter.');if(S.clues.length<2){showModal('Tableau des indices','Tu n’as pas encore assez d’indices pour comparer plusieurs pistes. Explore la bibliothèque, observe les couloirs et parle aux élèves. Une enquête solide commence par des faits.',()=>render());return}const score=S.clues.length+(S.skills.Sortilèges||0)+(S.skills.Métamorphose||0);const finding=score>=7?'Plusieurs indices convergent, mais deux détails restent à confirmer. Tu peux désormais distinguer la chronologie des événements des interprétations qui circulent.':score>=4?'Une première piste se dessine. Les dates et les témoignages donnent une direction, sans suffire à prouver toute l’hypothèse.':'Les indices sont intéressants, mais encore trop fragmentaires. Il te faut une source indépendante.';S.journal.push(`Année ${S.year} — Séance d’enquête : ${finding}`);if(score>=4){S.flags.investigationProgress=Math.max(S.flags.investigationProgress||0,score>=7?2:1);S.quests.push({title:'Vérifier la piste principale',description:'Trouve une nouvelle source et compare-la aux indices déjà notés.'})}autoSave();showModal('Tableau des indices',`<p>Indices réunis : <strong>${S.clues.length}</strong></p><ul>${S.clues.slice(-6).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(finding)}</p><p class="muted small">Cette synthèse n’invente pas de preuve : elle évalue seulement la quantité et la diversité de tes indices actuels.</p>`,()=>{render()})}
function studyDarkMagic(use){if(!S.started)return toast('Commence ton aventure avant de prendre cette décision.');if(use){if(S.flags.darkMagicUsed){toast('Tu as déjà expérimenté cette formule. Ses conséquences sont toujours présentes.');return}if(S.magic<15){toast('Ton énergie magique est trop faible pour tenter cette formule.');return}S.magic-=15;S.flags.darkMagicStudied=true;S.flags.darkMagicUsed=true;S.reputation.professors=Math.max(-10,S.reputation.professors-1);S.reputation.students=Math.min(10,S.reputation.students+1);S.relations['Hermione Granger']=Math.max(-5,(S.relations['Hermione Granger']||0)-1);S.journal.push(`Année ${S.year} — Tu as utilisé une formule risquée : un avantage immédiat, mais la confiance peut en souffrir.`);autoSave();render();showModal('Une décision qui laisse une trace','La formule fonctionne, mais l’effet ne s’efface pas dès que la lumière retombe. Tu as obtenu un avantage ponctuel et perdu une part de confiance. Les prochaines décisions ne répareront pas automatiquement cette conséquence.',()=>render())}else{S.flags.darkMagicStudied=true;S.skills.Défense=(S.skills.Défense||0)+1;S.reputation.professors=Math.min(10,S.reputation.professors+1);S.journal.push(`Année ${S.year} — Tu as étudié les risques d’une magie dangereuse sans l’utiliser.`);autoSave();render();showModal('Comprendre sans céder','Tu compares les témoignages, les effets et les limites de cette formule. Tu en sais davantage sur la manière de t’en défendre, sans créer la conséquence liée à son utilisation.',()=>render())}}
function socialVisit(name){if(!S.started)return toast('Crée ton personnage avant de rencontrer les autres.');const v=S.relations[name]||0;let msg='Vous échangez quelques mots. La relation reste ouverte : les prochains choix compteront davantage qu’une conversation isolée.';if(v>=3){msg=`${name} semble à l’aise avec toi. La conversation revient sur une décision passée et vous pouvez parler plus franchement de ce qui vous inquiète.`;S.relations[name]=Math.min(10,v+1);S.reputation.students=Math.min(10,S.reputation.students+1)}else if(v<=-2){msg=`${name} reste sur ses gardes. Tu peux écouter sans exiger une réconciliation immédiate ; la confiance ne se répare pas par une seule phrase.`;if(S.flags.mediatedDispute)S.relations[name]=Math.min(10,v+1)}else{msg=`${name} te parle d’un cours, d’une rumeur ou d’un projet pour le prochain temps libre. Tu découvres un peu mieux ses préoccupations.`;S.relations[name]=Math.min(10,v+1)}S.journal.push(`Année ${S.year} — Tu as pris des nouvelles de ${name}.`);autoSave();render();showModal(`Rencontre avec ${name}`,msg,()=>render())}
function spendTimeWithPet(){if(!S.started)return toast('Choisis ton compagnon pendant la création.');const animal=S.character.animal||'compagnon';let msg='Tu prends le temps de t’occuper de ton compagnon. La routine vous rapproche.';S.health=Math.min(100,S.health+5);S.magic=Math.min(100,S.magic+5);if(S.flags.portraitNoticed&&!S.flags.petNoticedClue){S.flags.petNoticedClue=true;S.clues.push(`Ton ${animal.toLowerCase()} réagit à un portrait qui semble différent de la veille.`);msg+=` Ton ${animal.toLowerCase()} s’arrête devant un portrait et attire ton attention sur un détail que tu avais déjà remarqué.`}S.journal.push(`Année ${S.year} — Tu as passé du temps avec ton ${animal.toLowerCase()}.`);autoSave();render();showModal('Un moment de calme',msg,()=>render())}
function shopBuy(item,cost){if(!S.started)return toast('Commence ton aventure avant de faire des achats.');if(S.galleons<cost){toast(`Il te faut ${cost} gallions pour cet achat.`);return}if(item==='Ingrédients de potion'&&S.inventory.includes('Ingrédients de potion')){toast('Tu possèdes déjà un lot d’ingrédients.');return}S.galleons-=cost;S.inventory.push(item);S.journal.push(`Année ${S.year} — Achat : ${item} (${cost} gallions).`);autoSave();render();toast(`${item} ajouté à l’inventaire.`)}
function useItem(index){const item=S.inventory[index];if(!item)return;if(item==='Potion de soin'){S.health=Math.min(100,S.health+35)}else if(item==='Potion de concentration'){S.magic=Math.min(100,S.magic+35)}else if(item==='Potion de protection'){S.health=Math.min(100,S.health+10);S.flags.protectionPotionReady=true}else if(item==='Livre de révision'){S.skills.Sortilèges++;S.skills.Potions++;S.skills.Défense++;S.inventory.splice(index,1)}else if(item==='Ingrédients de potion'){S.flags.ingredientsReady=true;toast('Tes ingrédients sont prêts pour la prochaine préparation.');return}else if(item==='Carnet d’enquête'||item==='Guide des symboles anciens'){S.clues.push('Une note personnelle t’invite à comparer les sources avant de conclure.');S.flags.investigationNotes=true}else if(item==='Friandise pour créature'){S.flags.creatureTreatReady=true}else{toast('Cet objet n’a pas d’utilisation directe pour le moment.');return}if(!['Livre de révision'].includes(item)&&item.startsWith('Potion'))S.inventory.splice(index,1);S.journal.push(`Année ${S.year} — Objet utilisé : ${item}.`);autoSave();render();toast(`${item} utilisé.`)}
function study(subject){if(!S.started){toast('Crée ton personnage pour accéder aux cours.');return}if(!Object.prototype.hasOwnProperty.call(S.skills,subject)){toast('Matière inconnue.');return}const studyKey=`study_${S.year}_${subject}`;if(S.flags[studyKey]){toast('Tu as déjà effectué cette séance de révision cette année. Reviens après la rentrée suivante.');return}S.flags[studyKey]=true;const gain=subject==='Potions'?2:1;S.skills[subject]=(S.skills[subject]||0)+gain;S.magic=Math.max(0,S.magic-3);S.reputation.professors=Math.min(10,S.reputation.professors+1);if((S.skills[subject]||0)%3===0)S.housePoints+=2;S.journal.push(`Année ${S.year} — Tu as révisé ${subject} lors d’une séance de travail.`);autoSave();render();toast(`${subject} : ta pratique progresse.`)}
function startDuel(){if(!S.started){toast('Crée ton personnage pour accéder aux duels.');return}if(S.duel?.active){toast('Un duel est déjà en cours. Termine-le avant d’en commencer un autre.');return}if(S.flags[`duel_${S.year}`]){toast('Tu as déjà disputé ton duel d’entraînement cette année.');return}S.duel={active:true,enemy:'Élève d’entraînement',enemyHP:100,round:0};S.page='activities';render();showModal('Duel d’entraînement','Ton adversaire se met en garde. À chaque tour, choisis une action : attaquer avec un sort connu, te protéger, esquiver ou reprendre ton souffle.',()=>{render()})}
function duelAction(action){if(!S.duel?.active)return;S.duel.round++;let msg='';if(action==='protego'){if(!S.spells.includes('Protego')){toast('Tu dois d’abord apprendre Protego.');return}if(S.magic<10){toast('Énergie magique insuffisante.');return}S.magic-=10;S.health=Math.min(100,S.health+4);msg='Protego absorbe une partie de l’impact.'}else if(action==='esquive'){S.health=Math.min(100,S.health+2);msg='Tu esquives et reprends ton équilibre.'}else if(action==='repos'){S.magic=Math.min(100,S.magic+18);msg='Tu reprends ton souffle et récupères de l’énergie.'}else{const sp=action;if(!S.spells.includes(sp)){toast('Ce sort ne figure pas encore dans ton grimoire.');return}const def=SPELLS.find(x=>x.name===sp);if(!def||S.magic<def.cost){toast('Énergie magique insuffisante.');return}S.magic-=def.cost;let damage=sp==='Expelliarmus'?30:sp==='Stupefix'?36:sp==='Accio'?12:sp==='Lumos'?5:18;damage+=Math.min(15,S.skills.Sortilèges*2);S.duel.enemyHP=Math.max(0,S.duel.enemyHP-damage);msg=`${sp} touche sa cible et inflige ${damage} points d’impact.`}if(S.duel.enemyHP<=0){S.duel.active=false;S.flags[`duel_${S.year}`]=true;S.reputation.students=Math.min(10,S.reputation.students+1);S.housePoints+=3;S.houseCup+=3;S.journal.push(`Année ${S.year} — Tu as remporté un duel d’entraînement.`);msg+=' Tu remportes le duel : +3 points pour ta maison.'}else{const enemyDamage=action==='protego'?4:action==='esquive'?2:action==='repos'?13:8;S.health=Math.max(1,S.health-enemyDamage);msg+=` Ton adversaire riposte et te fait perdre ${enemyDamage} points de santé.`}autoSave();render();showModal(S.duel?.active?'Le duel continue':'Duel terminé',`${msg}<br><br><strong>Adversaire : ${S.duel?.enemyHP??0}%</strong> · Santé : ${S.health}% · Énergie : ${S.magic}%`,()=>render())}
function beginPotion(type){if(!S.started)return toast('Crée ton personnage pour préparer des potions.');const recipes={soin:{name:'Potion de soin',cost:3,desc:'La préparation apaise tes blessures.'},concentration:{name:'Potion de concentration',cost:2,desc:'La préparation aide à retrouver de l’énergie magique.'},protection:{name:'Potion de protection',cost:4,desc:'La préparation offre un petit soutien avant un défi.'}};const r=recipes[type];if(!r)return;if(!S.inventory.includes('Ingrédients de potion')){if(S.galleons<r.cost){toast(`Il te faut ${r.cost} gallions pour acheter les ingrédients.`);return}S.galleons-=r.cost;}else S.inventory.splice(S.inventory.indexOf('Ingrédients de potion'),1);S.potionLab={active:true,type,name:r.name,desc:r.desc,step:0,errors:0};S.journal.push(`Année ${S.year} — Tu as commencé la préparation de ${r.name}.`);autoSave();render()}
function potionStep(method){if(!S.potionLab?.active)return;const lab=S.potionLab;if(method==='intuitif'&&((S.skills.Potions||0)<2)){lab.errors++;}else if(method==='intuitif'&&((S.skills.Potions||0)>=2)){lab.errors=Math.max(0,lab.errors-1)}lab.step++;if(lab.step<3){autoSave();render();return}const success=lab.errors===0||(S.skills.Potions||0)>=3;S.skills.Potions=(S.skills.Potions||0)+1;let result='';if(success){if(lab.type==='soin'){S.health=Math.min(100,S.health+35)}else if(lab.type==='concentration'){S.magic=Math.min(100,S.magic+35)}else{S.health=Math.min(100,S.health+10);S.flags.protectionPotionReady=true}S.inventory.push(lab.name);result=`La préparation est réussie. ${lab.desc} Elle est rangée dans ton inventaire.`;S.journal.push(`Année ${S.year} — Tu as réussi ${lab.name}.`)}else{S.inventory.push('Notes de potion imparfaite');result='La potion n’est pas assez stable pour être utilisée. Tu conserves tes notes et comprends quelle étape revoir.';S.journal.push(`Année ${S.year} — Ta préparation de ${lab.name} a été imparfaite ; tu as conservé tes notes.`)}S.potionLab={active:false};autoSave();render();showModal(success?'Potion réussie':'Préparation imparfaite',result,()=>render())}
function cancelPotion(){if(!S.potionLab?.active)return;S.potionLab={active:false};S.journal.push(`Année ${S.year} — Tu as interrompu une préparation avant de la terminer.`);autoSave();render();toast('Préparation interrompue. Les ingrédients utilisés ne sont pas récupérés.')}
function brewPotion(type){beginPotion(type)}
function quidditchTryout(){if(!S.started)return toast('Crée ton personnage avant les essais.');if(S.year<2){showModal('Essai de Quidditch','Tu peux t’entraîner dès maintenant, mais l’équipe ne recrute pas encore les élèves de première année. Reviens plus tard, et continue à travailler les passes et la coordination.',()=>render());return}const trained=S.quidditch.trained||0;const score=trained+(S.skills.Défense||0)+(S.reputation.students>1?1:0);if(score>=2){S.quidditch.joined=true;S.quidditch.position=S.skills.Défense>=2?'Poursuiveur':'Remplaçant';S.journal.push(`Année ${S.year} — Tu as obtenu une place dans l’équipe de Quidditch comme ${S.quidditch.position}.`);S.reputation.students=Math.min(10,S.reputation.students+1);autoSave();render();showModal('Une place dans l’équipe',`Le capitaine a remarqué ton travail. Tu rejoins l’équipe comme ${esc(S.quidditch.position)}. Ta place dépendra toujours de l’entraînement et des décisions prises pendant les matchs.`,()=>render())}else{S.quidditch.trained++;S.journal.push(`Année ${S.year} — Ton essai de Quidditch est reporté : tu dois encore gagner en coordination.`);autoSave();render();showModal('Pas encore',`Le capitaine te conseille de poursuivre l’entraînement. Tu n’es pas exclu définitivement : améliore ta coordination et reviens tenter ta chance.`,()=>render())}}
function playQuidditch(action){if(!S.started)return toast('Crée ton personnage pour jouer.');if(!S.quidditch.joined&&action!=='entrainement'){if(action==='passe'){S.quidditch.trained=(S.quidditch.trained||0)+1;S.skills.Défense=(S.skills.Défense||0)+1;S.journal.push(`Année ${S.year} — Entraînement de Quidditch : tu travailles les passes.`);autoSave();render();toast('Entraînement terminé : coordination améliorée.');return}toast('Tu dois intégrer l’équipe avant de jouer un match officiel.');return}S.quidditch.trained=(S.quidditch.trained||0)+1;let score=0,msg='';if(action==='passe'){score=2+(S.quidditch.trained%3);msg='Une passe précise ouvre une occasion.'}else if(action==='attaque'){score=1+(S.skills.Défense>1?2:0);msg='Tu tentes une attaque directe.'}else{score=1;S.reputation.students=Math.min(10,S.reputation.students+1);msg='Tu protèges un coéquipier et gardes l’équipe organisée.'}const roll=Math.min(4,Math.floor((S.quidditch.trained||0)/2)+(S.skills.Défense||0));const win=score+roll>=5;if(win){S.quidditch.wins=(S.quidditch.wins||0)+1;S.housePoints+=3;S.reputation.house=Math.min(10,S.reputation.house+1);S.journal.push(`Année ${S.year} — Ton équipe a remporté un match d’entraînement de Quidditch.`);msg+=' Votre action fait basculer le match en votre faveur : +3 points de maison.'}else{S.reputation.students=Math.max(-10,S.reputation.students-1);msg+=' L’action échoue, mais tu identifies un point à travailler.'}autoSave();render();showModal('Quidditch',`${msg}<br><br>Entraînements : ${S.quidditch.trained} · Victoires : ${S.quidditch.wins}`,()=>render())}
function creatureEncounter(action){if(!S.started)return toast('Crée ton personnage pour commencer.');let msg='';if(action==='observer'){S.skills.Potions=(S.skills.Potions||0)+1;S.clues.push('Une créature réagit au bruit et aux mouvements brusques.');msg='En observant à distance, tu repères les signes de peur et comprends qu’il faut éviter les gestes brusques.'}else if(action==='nourrir'){if(S.galleons<1){toast('Il te faut au moins 1 gallion pour acheter un ingrédient.');return}S.galleons--;S.reputation.students=Math.min(10,S.reputation.students+1);S.inventory.push('Confiance d’une créature (souvenir)');msg='Tu déposes un ingrédient puis recules. La créature s’approche à son rythme. La confiance n’est pas garantie, mais ton approche était respectueuse.'}else{if(S.skills.Potions>0){S.relations['Neville Londubat']=Math.min(10,(S.relations['Neville Londubat']||0)+1);msg='Grâce à ce que tu as appris, tu reconnais les signes d’apaisement. La créature te laisse rester à proximité.'}else{S.health=Math.max(1,S.health-3);msg='Tu avances trop vite et la créature recule brusquement. Tu t’éloignes sans la poursuivre et retiens la leçon.'}}S.journal.push(`Année ${S.year} — Rencontre avec une créature : ${action}.`);autoSave();render();showModal('Rencontre magique',msg,()=>render())}
function freeTime(kind){if(!S.started)return toast('Crée ton personnage pour commencer.');if(kind==='friends'){S.relations['Ron Weasley']=Math.min(10,(S.relations['Ron Weasley']||0)+1);S.relations['Harry Potter']=Math.min(10,(S.relations['Harry Potter']||0)+1);S.magic=Math.min(100,S.magic+5);S.journal.push(`Année ${S.year} — Tu as passé un moment avec tes amis.`);toast('Un moment partagé renforce les liens.')}else if(kind==='study'){S.skills.Sortilèges++;S.skills.Potions++;S.magic=Math.max(0,S.magic-5);S.journal.push(`Année ${S.year} — Tu as étudié au calme.`);toast('Tes notes progressent.')}else{S.health=Math.min(100,S.health+20);S.magic=Math.min(100,S.magic+25);S.journal.push(`Année ${S.year} — Tu as pris du repos.`);toast('Tu as récupéré.')}autoSave();render()}


// Scènes de vacances et de transition pour les années suivantes.
YEARS[1].push({title:'Noël, loin des couloirs',place:'Vacances de Noël',text:'La neige couvre les fenêtres et le château ralentit son rythme. Une lettre arrivée de chez toi contient une question inattendue sur ta vie à Poudlard. Tu peux répondre avec franchise, ou protéger certains détails tant que tu ne sais pas comment les expliquer.',choices:[{label:'Raconter un souvenir important de l’année',desc:'Partager ce qui t’a changé depuis la rentrée.',effect:{relations:{'Harry Potter':1},journal:'Pendant les vacances de Noël, tu as partagé un souvenir important.'},next:'La réponse qui revient quelques jours plus tard montre que tes proches essaient de comprendre la personne que tu deviens.'},{label:'Garder le mystère et écrire une réponse plus légère',desc:'Choisir le bon moment pour parler.',effect:{flags:{holidaySecret:true},galleons:2,journal:'Tu as choisi de garder certains détails pour plus tard pendant les vacances.'},next:'Tu ne mens pas, mais tu n’expliques pas tout. Cette réserve te laisse du temps pour trouver les mots justes.'}]});
YEARS[2].push({title:'Les vacances et les vieux souvenirs',place:'Maison familiale',text:'Loin de Poudlard, un objet familier te rappelle une question laissée en suspens. Un membre de ta famille se souvient d’un détail que tu n’avais jamais pris au sérieux. Le souvenir n’explique pas tout, mais il donne une nouvelle direction à tes recherches.',choices:[{label:'Demander à entendre toute l’histoire',desc:'Accepter que les réponses soient parfois incomplètes.',effect:{flags:{familyMemory:true},clue:'Un souvenir familial confirme un détail déjà aperçu dans les archives.',journal:'Tu as interrogé ta famille au sujet d’un ancien souvenir.'},next:'Le récit comporte des zones floues, mais un détail correspond à une note de ton journal. Tu sais maintenant quelle question poser à la rentrée.'},{label:'Ne pas insister et profiter du temps ensemble',desc:'Les liens comptent même sans révélation immédiate.',effect:{relations:{'Neville Londubat':1},health:10,journal:'Tu as choisi de profiter des vacances sans forcer une révélation.'},next:'La conversation s’arrête là, sans déception. Parfois, le bon moment pour une vérité vient plus tard.'}]});
YEARS[3].push({title:'Le retour du printemps',place:'Parc de Poudlard',text:'Les premières journées plus douces donnent au château une apparence presque paisible. Pourtant, les examens approchent et une rumeur sur la Coupe des Maisons circule déjà. Tu dois choisir où placer ton énergie : aider ton équipe, réviser ou profiter d’un moment avec tes proches.',choices:[{label:'Organiser des révisions avec des camarades',desc:'Transformer le stress en entraide concrète.',effect:{skills:{Sortilèges:1,Potions:1},relations:{'Hermione Granger':1},housePoints:2,journal:'Tu as organisé des révisions collectives au printemps.'},next:'Les révisions ne suppriment pas la pression, mais chacun repart avec une meilleure compréhension et une liste claire de ce qu’il doit revoir.'},{label:'Prendre un moment de repos avant les examens',desc:'Préserver son énergie est aussi une décision stratégique.',effect:{health:15,magic:15,journal:'Tu as pris le temps de récupérer avant les examens.'},next:'Tu retournes aux révisions avec l’esprit plus clair. Tu ne peux pas tout préparer, mais tu as évité de t’épuiser avant l’épreuve.'}]});
YEARS[4].push({title:'Une lettre pendant les fêtes',place:'Vacances de Noël',text:'Une lettre attend près de la cheminée, mais l’écriture sur l’enveloppe te surprend. Elle vient d’une personne avec laquelle les choses sont devenues compliquées. Le message ne demande pas un pardon immédiat ; il propose simplement de parler après les vacances.',choices:[{label:'Répondre et accepter une conversation prudente',desc:'Laisser une possibilité sans oublier le passé.',effect:{relations:{'Drago Malefoy':1},flags:{winterConversation:true},journal:'Tu as accepté de laisser une conversation difficile ouverte.'},next:'Ta réponse ne règle pas le conflit, mais elle crée une possibilité de dialogue. À la rentrée, tu devras juger la suite sur les actes plutôt que sur les mots.'},{label:'Ne pas répondre avant d’avoir réfléchi',desc:'Le silence peut être une limite nécessaire.',effect:{flags:{winterNoReply:true},journal:'Tu as choisi de ne pas répondre immédiatement à une lettre difficile.'},next:'Tu ranges la lettre avec tes notes. Tu ne sais pas encore si tu répondras, et cette incertitude t’appartient.'}]});
YEARS[5].push({title:'L’été des questions difficiles',place:'Maison familiale',text:'L’été t’offre une distance bienvenue, mais pas l’oubli. Tu relis tes notes et remarques combien tes priorités ont changé. Ta famille voit aussi que tu n’es plus tout à fait l’enfant qui est parti à Poudlard. Une conversation s’impose sur ce que tu veux protéger et sur ce que tu es prêt à risquer.',choices:[{label:'Expliquer ce qui te préoccupe sans tout révéler',desc:'Partager assez pour ne plus porter seul le poids des décisions.',effect:{flags:{familySupport:true},health:10,relations:{'Harry Potter':1},journal:'Tu as parlé de tes inquiétudes pendant les vacances d’été.'},next:'Tu n’as pas donné tous les détails, mais tu as accepté de demander du soutien. Cette conversation te permet de reprendre la route avec moins de poids sur les épaules.'},{label:'Garder tes préoccupations pour ton journal',desc:'Mettre de l’ordre dans tes pensées avant de parler.',effect:{skills:{Défense:1},clue:'Une note personnelle relie deux événements jusque-là séparés.',journal:'Tu as utilisé ton journal pour clarifier tes priorités pendant l’été.'},next:'L’écriture fait apparaître un lien entre deux événements. Tu ne sais pas encore ce qu’il signifie, mais tu as désormais une question précise à vérifier.'}]});
YEARS[6].push({title:'La veille de la confrontation',place:'Salle commune',text:'La dernière nuit de préparation est traversée de conversations à voix basse. Une lettre de ta famille, quelques mots d’un ami et les notes de ton journal rappellent ce que tu ne veux pas perdre. Tu ne peux pas garantir l’issue de demain, mais tu peux décider comment y entrer.',choices:[{label:'Écrire une lettre que tu remettras après l’épreuve',desc:'Garder un lien avec la vie qui t’attend au-delà du danger.',effect:{flags:{lastLetter:true},health:5,journal:'Tu as écrit une lettre pour l’après, quelle que soit l’issue.'},next:'Tu plies la lettre et la confies à un endroit sûr. Ce geste ne promet pas une fin heureuse ; il affirme simplement qu’un avenir mérite d’être envisagé.'},{label:'Passer une dernière soirée avec tes alliés',desc:'Se rappeler pourquoi chacun a choisi de rester.',effect:{relations:{'Harry Potter':1,'Ron Weasley':1,'Hermione Granger':1},magic:10,journal:'Tu as partagé une dernière soirée avec tes alliés.'},next:'La soirée est faite de silences, de souvenirs et de plaisanteries trop faibles pour masquer la peur. Mais vous entrez dans la nuit en sachant que vous n’êtes pas seuls.'}]});


// Chapitres supplémentaires : progression scolaire, mystères, relations, vacances et conclusions propres à chaque année.
const EXTRA_SCENES = [[["Le premier cours de sortilèges","Salle de classe","La salle sent la craie, le bois ciré et la pluie sur les manteaux. Le professeur vous demande de faire léviter une plume, mais l’exercice révèle surtout les habitudes de chacun. Certains forcent leur geste, d’autres observent longtemps. Tu peux suivre la méthode à la lettre ou chercher à comprendre pourquoi ta baguette réagit différemment selon ton intention.",[["Recommencer lentement en suivant chaque étape","La précision avant la vitesse.",{"skills":{"Sortilèges":1},"housePoints":2,"reputation":{"professors":1},"journal":"Tu as appris à décomposer un sortilège en étapes."},"La plume monte de quelques centimètres, vacille, puis reste en l’air. Le professeur souligne ta patience. Tu comprends qu’un geste simple peut demander davantage de maîtrise qu’un grand effet spectaculaire."],["Observer les essais des autres avant de tenter une autre approche","Apprendre aussi des erreurs des autres.",{"skills":{"Sortilèges":1},"relations":{"Hermione Granger":1},"clue":"La concentration change la stabilité de la plume.","journal":"Tu as observé plusieurs méthodes avant de choisir la tienne."},"Tu remarques que les gestes les plus précis ne sont pas forcément les plus amples. En reprenant l’exercice, tu trouves un mouvement plus naturel. Une plume ne prouve pas tout, mais elle t’a appris à observer."]]],["Une note sous la porte","Couloir du troisième étage","Au retour du dîner, un petit morceau de parchemin dépasse de la porte de la salle commune. Il ne porte aucun nom, seulement trois mots : « La pierre se souvient ». L’écriture semble récente, mais le papier est jauni sur les bords. Tu ignores si cette note t’est destinée ou si quelqu’un espère que tu la trouveras.",[["Comparer le papier à tes anciens indices","Chercher des faits avant d’imaginer une explication.",{"skills":{"Sortilèges":1},"clue":"La note a été écrite récemment sur un papier ancien.","flags":{"mysteriousNoteExamined":true},"journal":"Tu as examiné une note anonyme sans lui faire confiance."},"L’encre est récente, mais le papier a été découpé dans un vieux registre. La phrase semble donc être un message volontaire, pas une relique oubliée. Tu ajoutes la provenance à ton carnet."],["En parler à une personne de confiance","Ne pas porter seul un mystère incertain.",{"relations":{"Ron Weasley":1,"Hermione Granger":1},"flags":{"mysteriousNoteShared":true},"journal":"Tu as partagé la note anonyme avec des camarades."},"La note suscite plus de questions que de réponses. Vous décidez de ne pas vous aventurer dans un couloir interdit sur la seule foi d’un message. Pour l’instant, vous conservez le papier comme indice."]]],["Le dîner des premières semaines","Grande Salle","Les conversations deviennent plus familières. À ta table, un élève raconte une histoire exagérée pour faire rire les autres, tandis qu’une camarade reste silencieuse après une remarque blessante. Tu peux préserver l’ambiance en ne t’en mêlant pas ou prendre le risque d’intervenir, sans être certain de la réaction du groupe.",[["Détourner la conversation sans humilier personne","Désamorcer sans transformer la soirée en dispute.",{"relations":{"Neville Londubat":1,"Ron Weasley":1},"reputation":{"students":1},"journal":"Tu as aidé à apaiser une conversation tendue."},"Tu poses une question sur les cours qui entraîne la table vers un autre sujet. La tension retombe peu à peu. La camarade te remercie d’un regard, même si personne ne fait de discours sur ce qui vient de se passer."],["Dire calmement que la remarque a dépassé les limites","Accepter un moment de malaise pour défendre quelqu’un.",{"relations":{"Neville Londubat":2},"reputation":{"students":1},"housePoints":1,"journal":"Tu as pris la parole lorsqu’un camarade a été blessé."},"Le silence dure quelques secondes. La personne qui a parlé se défend, puis finit par changer de ton. Tu ne gagnes pas l’approbation de tout le monde, mais quelqu’un se souviendra que tu as refusé de rire aux dépens d’un autre."]]],["La première nuit de neige","Tour de ta maison","La neige tombe sur les toits et étouffe les bruits du parc. Depuis une fenêtre, tu aperçois une lueur qui se déplace près d’un vieux mur avant de disparaître. Le lendemain, personne ne semble avoir remarqué quoi que ce soit. Tu as un examen à préparer et peu d’éléments pour savoir si cette lueur mérite une enquête.",[["Noter l’heure et chercher une explication le lendemain","La curiosité peut attendre un moment plus sûr.",{"clue":"Une lueur a été aperçue près du vieux mur après le couvre-feu.","skills":{"Métamorphose":1},"journal":"Tu as consigné une observation nocturne avant d’agir."},"Tu dessines l’emplacement et l’heure dans ton journal. À la lumière du jour, tu remarques que la fenêtre reflète un vitrail de la tour opposée. Ce n’est pas une solution complète, mais tu as éliminé une première fausse piste."],["Demander à un préfet si des rondes ont été signalées","Privilégier la sécurité et les informations vérifiables.",{"reputation":{"professors":1},"flags":{"askedPrefectAboutLight":true},"journal":"Tu as demandé conseil avant de suivre une piste nocturne."},"Le préfet confirme qu’une ronde a eu lieu, sans pouvoir expliquer la lumière. Il te rappelle que les couloirs ne sont pas tous sûrs la nuit. Tu décides de poursuivre l’enquête de jour."]]]],[["Un devoir qui résiste","Salle de classe","L’exercice du jour semble simple sur le papier, mais ton résultat reste instable. Une formule répétée plus fort ne change rien. Tu peux demander au professeur de revoir le geste avec toi, ou comparer tes notes avec celles d’un élève dont la méthode paraît très différente de la tienne.",[["Demander une correction précise au professeur","Accepter de montrer ce que tu ne maîtrises pas encore.",{"skills":{"Sortilèges":1},"reputation":{"professors":1},"housePoints":2,"journal":"Tu as demandé une correction ciblée pendant un cours."},"Le professeur corrige l’angle de ton poignet et t’invite à ralentir. Le sort devient plus stable au troisième essai. Tu repars avec une méthode que tu peux réutiliser plutôt qu’avec une réussite due à la chance."],["Comparer les notes avec un camarade","Une autre manière de penser peut débloquer l’exercice.",{"relations":{"Hermione Granger":1},"skills":{"Sortilèges":1},"journal":"Tu as comparé deux méthodes d’apprentissage."},"Vos notes ne disent pas exactement la même chose, mais leur différence explique ton erreur. En combinant les deux approches, tu trouves une méthode qui te convient davantage."]]],["La salle absente","Archives de Poudlard","Le plan ancien et le plan actuel ne s’accordent pas. Une alcôve dessinée sur le document ancien semble correspondre à un espace vide derrière une tapisserie. La pierre n’a pourtant aucune poignée ni serrure visible. Tu peux chercher une formule qui réagit au mur ou vérifier les archives de rénovation.",[["Examiner le mur avec un sort de lumière","Révéler les détails sans forcer le passage.",{"magic":-3,"clue":"De fines rainures forment un motif autour d’une pierre déplacée.","flags":{"wallInspected":true},"journal":"Tu as découvert des rainures autour d’un mur ancien."},"La lumière accroche des rainures presque invisibles. Elles dessinent une forme incomplète, comme si une partie du mécanisme avait été retirée. Le mur ne s’ouvre pas, mais tu sais maintenant que l’anomalie est réelle."],["Consulter les registres de travaux","L’histoire d’un lieu peut expliquer sa transformation.",{"skills":{"Métamorphose":1},"clue":"Un chantier ancien a condamné une alcôve pour des raisons jamais détaillées.","reputation":{"professors":1},"journal":"Tu as recherché l’histoire d’un passage dans les archives."},"Le registre mentionne une modification urgente, sans en donner le motif. La signature est illisible. Tu as trouvé une date fiable et une question plus précise à poser."]]],["Une invitation inattendue","Salle commune","Un camarade avec qui tu as peu parlé t’invite à rejoindre un petit groupe de révision. L’invitation paraît sincère, mais tu sais qu’un autre élève du groupe ne t’apprécie guère. Refuser préserverait ton calme ; accepter pourrait changer une relation qui n’a jamais vraiment eu l’occasion de commencer.",[["Accepter et proposer que chacun explique sa méthode","Créer un terrain commun plutôt que chercher à impressionner.",{"relations":{"Hermione Granger":1,"Neville Londubat":1},"skills":{"Potions":1},"journal":"Tu as participé à une révision collective."},"La séance n’est pas parfaite : certains s’impatientent et les notes se mélangent. Pourtant, une explication donnée simplement débloque un exercice pour tout le monde. Le groupe t’invite à revenir."],["Décliner poliment et proposer un autre moment","Respecter tes limites sans fermer la porte.",{"health":5,"flags":{"studyInviteDeferred":true},"journal":"Tu as décliné une invitation sans rompre le contact."},"Tu expliques que tu dois terminer un travail. La réponse est un peu froide, mais tu proposes un autre moment. Tu gardes ton temps libre sans transformer un refus en rupture."]]],["Les lumières de la serre","Serres","À la tombée du jour, des points lumineux apparaissent entre les vitres. Ils suivent un rythme irrégulier, comme s’ils répondaient au vent. Une caisse de matériel est restée ouverte à proximité. Tu te souviens que certaines plantes réagissent à la chaleur et aux sons, mais tu ne connais pas encore cette espèce.",[["Observer depuis l’allée et consigner les variations","Laisser l’environnement révéler son fonctionnement.",{"skills":{"Potions":1},"clue":"Les lumières de la serre répondent aux variations de température.","journal":"Tu as observé un phénomène végétal sans perturber la serre."},"Après quelques minutes, les lumières diminuent quand le courant d’air s’arrête. Tu ne connais pas encore toute la plante, mais tu peux écarter l’idée d’une présence qui te suivrait."],["Prévenir le responsable des serres","Demander un avis avant de toucher à une espèce inconnue.",{"reputation":{"professors":1},"housePoints":2,"inventoryAdd":"Fiche botanique annotée","journal":"Tu as demandé conseil au sujet d’une plante inconnue."},"Le responsable identifie une plante luminescente sensible à la température. Il te remet une fiche d’observation et apprécie que tu n’aies pas arraché de feuilles pour satisfaire ta curiosité."]]]],[["Une sortie à Pré-au-Lard","Pré-au-Lard","La rue principale est animée par les conversations, les vitrines et l’odeur du pain chaud. Un commerçant te reconnaît à cause d’une question posée lors d’une précédente visite. Il propose de te montrer un objet ancien, mais refuse d’expliquer pourquoi il le garde derrière le comptoir.",[["Poser des questions sur la provenance de l’objet","La curiosité gagne à s’accompagner de prudence.",{"galleons":-2,"clue":"Un objet ancien porte le même motif que les notes des archives.","journal":"Tu as interrogé un commerçant sur un objet ancien."},"L’objet n’est pas magique au sens spectaculaire du terme, mais son motif correspond à une marque de tes archives. Le commerçant ne sait pas tout de son histoire. Tu repars avec une piste, pas une certitude."],["Ne rien acheter et demander où consulter des archives locales","Chercher une source avant de croire une histoire.",{"skills":{"Sortilèges":1},"reputation":{"students":1},"journal":"Tu as privilégié une source vérifiable à un achat impulsif."},"Le commerçant te conseille une petite collection d’histoire locale. Tu n’as rien dépensé, mais tu sais où trouver une description indépendante de l’objet."]]],["L’exercice de défense","Salle de classe","Le professeur organise un exercice où chaque élève doit protéger un objet tout en évitant les sorts d’un partenaire. La victoire dépend moins de la force que de la lecture du rythme adverse. Tu peux te concentrer sur la défense ou tenter de prévoir le prochain mouvement de ton partenaire.",[["Maintenir une défense stable et attendre une ouverture","La patience peut être une stratégie active.",{"skills":{"Défense":2},"magic":-5,"housePoints":2,"journal":"Tu as privilégié la défense et l’observation lors d’un exercice."},"Tu résistes aux premières feintes et repères un rythme répétitif. Au moment opportun, tu récupères l’objet sans geste spectaculaire. Le professeur souligne que tu as su attendre plutôt que réagir à chaque provocation."],["Changer de position pour briser le rythme","Prendre l’initiative sans perdre de vue l’objectif.",{"skills":{"Défense":1,"Sortilèges":1},"health":-3,"journal":"Tu as tenté une stratégie mobile pendant un exercice de défense."},"Ton déplacement surprend ton partenaire, mais tu laisses une ouverture et reçois un impact léger. Tu réussis tout de même l’exercice. Tu retiens qu’une bonne stratégie doit prévoir le risque créé par son propre mouvement."]]],["Le souvenir partagé","Parc du lac","Un ami te demande de raconter un souvenir qui t’aide lorsque tu doutes. Il ne cherche pas une réponse parfaite, seulement à comprendre ce qui te permet de continuer. En parlant, tu découvres que le souvenir a changé de sens depuis ton arrivée à Poudlard.",[["Partager le souvenir sans chercher à le rendre héroïque","La vérité d’un souvenir compte plus que son apparence.",{"patronusStage":1,"relations":{"Harry Potter":1},"flags":{"patronusMemoryShared":true},"journal":"Tu as identifié un souvenir important dans ton apprentissage du Patronus."},"Tu racontes les détails ordinaires que tu avais presque oubliés. Ils donnent au souvenir une force nouvelle. La magie ne répond pas encore, mais tu comprends qu’un Patronus ne se résume pas à une image heureuse."],["Garder le souvenir privé et expliquer ce qu’il représente","Tu peux protéger l’intimité tout en avançant.",{"patronusStage":1,"skills":{"Défense":1},"journal":"Tu as travaillé sur le sens d’un souvenir personnel."},"Tu ne racontes pas l’événement lui-même, mais tu nommes ce qu’il t’a appris. Cela suffit à rendre l’exercice moins abstrait. Tu gardes ton intimité et avances malgré tout."]]],["Une créature blessée","Lisière de la forêt","Un bruissement révèle une petite créature coincée dans des branches basses. Elle montre les dents quand tu approches, davantage par peur que par agressivité. Le sentier est encore visible derrière toi et tu peux demander de l’aide, mais chaque minute semble la fatiguer davantage.",[["Dégager lentement les branches sans toucher la créature","Réduire la menace avant de tenter d’aider.",{"skills":{"Défense":1},"flags":{"creatureRescued":true},"inventoryAdd":"Fil végétal résistant","journal":"Tu as aidé une créature en respectant sa peur."},"Tu retires une branche à la fois et recules chaque fois que la créature s’agite. Elle finit par se libérer et disparaît dans les fourrés. Tu trouves un fil végétal étonnamment solide, tombé près du piège."],["Revenir chercher un adulte compétent","La prudence peut être la meilleure forme de courage.",{"reputation":{"professors":1},"housePoints":2,"relations":{"Neville Londubat":1},"journal":"Tu es revenu avec de l’aide pour une créature en difficulté."},"L’adulte arrive avec le matériel nécessaire et libère la créature sans la blesser. Il t’explique les signes qui indiquaient sa peur. Tu as perdu quelques minutes, mais tu as choisi une solution sûre."]]]],[["Le bal des décisions","Grande Salle","La salle a changé d’apparence pour une soirée officielle : lumières douces, tables repoussées et conversations plus prudentes qu’à l’habitude. Une invitation te place entre deux personnes qui ne s’entendent pas. Tu peux tenter de rapprocher leurs points de vue ou choisir de ne pas devenir l’arbitre de leur conflit.",[["Proposer une conversation autour d’un sujet commun","Construire un espace de dialogue sans forcer une réconciliation.",{"relations":{"Hermione Granger":1,"Ron Weasley":1},"reputation":{"students":1},"journal":"Tu as tenté de désamorcer une tension lors d’une soirée."},"La conversation reste fragile, mais un sujet commun détourne les deux personnes de leur dispute. Elles ne deviennent pas amies d’un coup. Tu as simplement créé une soirée où elles n’ont pas eu besoin de s’affronter."],["Profiter de la soirée sans prendre parti","Tu n’as pas à résoudre tous les conflits.",{"health":5,"flags":{"avoidedPartyConflict":true},"journal":"Tu as choisi de ne pas arbitrer un conflit qui ne t’appartenait pas."},"Tu changes de groupe et retrouves des personnes avec qui tu peux être toi-même. Le conflit n’est pas réglé, mais tu évites d’ajouter une parole maladroite à une situation déjà tendue."]]],["Le laboratoire verrouillé","Donjons","Une salle de préparation reste fermée après un cours, et une odeur inhabituelle se dégage de la porte. Le registre indique qu’aucune séance n’est prévue. Forcer la serrure serait imprudent ; tu peux signaler le problème ou tenter d’identifier l’odeur depuis le couloir.",[["Prévenir le professeur responsable","La sécurité passe avant la curiosité.",{"reputation":{"professors":2},"housePoints":2,"journal":"Tu as signalé une anomalie dans une salle de préparation."},"Le professeur découvre qu’un récipient mal fermé a laissé s’échapper une vapeur irritante. Il te remercie d’avoir signalé le problème plutôt que d’entrer. Une petite décision évite une situation bien plus sérieuse."],["Identifier l’odeur à distance et noter tes observations","Utiliser ce que tu sais sans franchir la limite.",{"skills":{"Potions":1},"clue":"L’odeur correspond à un ingrédient de potion instable lorsqu’il est chauffé.","journal":"Tu as identifié à distance un indice lié à une potion."},"Tu reconnais une note métallique caractéristique d’un ingrédient chauffé. Tu n’ouvres pas la porte et transmets tes observations. Le professeur confirme plus tard ton hypothèse et te montre comment reconnaître ce signe."]]],["La vérité derrière le témoignage","Salle d’étude","Un indice récent contredit une conclusion que tu défends depuis plusieurs semaines. L’admettre pourrait fragiliser la confiance d’un ami qui t’a aidé, mais l’ignorer rendrait ton enquête moins solide. Tu dois choisir entre protéger une hypothèse ou accepter de la réviser.",[["Corriger ton carnet et expliquer ce qui a changé","La fiabilité d’une enquête dépend aussi de ses corrections.",{"clue":"Une hypothèse précédente a été révisée à la lumière d’un nouvel indice.","relations":{"Hermione Granger":1},"reputation":{"professors":1},"journal":"Tu as corrigé une hypothèse après l’apparition d’un nouvel indice."},"Ton ami est déçu d’avoir suivi une piste qui ne tient plus, mais comprend que tu ne veux pas maquiller les faits. L’enquête repart sur une base plus solide, même si elle semble reculer."],["Conserver l’hypothèse en attendant une seconde vérification","Le doute peut justifier une pause, pas un déni.",{"flags":{"hypothesisPending":true},"clue":"Une contradiction reste à vérifier avant de conclure.","journal":"Tu as laissé une hypothèse en suspens plutôt que de la trancher trop vite."},"Tu notes clairement la contradiction au lieu de l’effacer. La piste reste ouverte, mais ton carnet distingue désormais ce que tu sais de ce que tu supposes."]]],["La veille des examens","Bibliothèque","Les révisions s’étirent jusqu’à ce que les lignes se brouillent. Un ami veut continuer malgré sa fatigue, tandis qu’un autre propose de revoir ensemble les notions les plus difficiles. Tu peux pousser encore un peu ou organiser une séance courte qui laisse du temps au repos.",[["Faire une révision collective ciblée puis s’arrêter","Une méthode réaliste vaut mieux qu’une nuit blanche.",{"skills":{"Potions":1,"Sortilèges":1},"relations":{"Hermione Granger":1},"health":8,"housePoints":2,"journal":"Tu as organisé une révision équilibrée avant les examens."},"Vous choisissez trois notions et vous vous interrogez à tour de rôle. Tout n’est pas parfait, mais chacun identifie ce qu’il maîtrise. Vous partez vous reposer avant que la fatigue ne ruine le travail accompli."],["Continuer seul jusqu’à maîtriser un point précis","La concentration peut aider, à condition de poser une limite.",{"skills":{"Sortilèges":1},"health":-5,"journal":"Tu as prolongé tes révisions pour comprendre un point difficile."},"Tu finis par comprendre le point qui te résistait, mais tu arrives au lendemain avec les yeux lourds. Le progrès est réel et le coût aussi : tu devras apprendre à reconnaître le moment où il faut s’arrêter."]]]],[["Un décret contesté","Couloir principal","Une nouvelle règle limite certaines activités étudiantes. Les conversations se tendent, et plusieurs élèves veulent réagir immédiatement. Tu peux organiser une réponse calme et documentée ou aider discrètement les élèves qui risquent d’être les plus pénalisés.",[["Rassembler des faits et rédiger une demande argumentée","La précision rend une contestation plus difficile à écarter.",{"reputation":{"students":2,"professors":-1},"housePoints":-1,"flags":{"petitionPrepared":true},"journal":"Tu as participé à une contestation argumentée d’une règle."},"Le texte ne change pas immédiatement la règle, mais il oblige les responsables à répondre à des questions précises. Certains élèves te soutiennent, d’autres trouvent ta démarche trop prudente. Tu as choisi une voie visible, avec ses coûts."],["Aider les élèves concernés sans te placer au centre","Le soutien discret peut compter autant qu’une déclaration.",{"relations":{"Neville Londubat":2},"reputation":{"students":1},"journal":"Tu as aidé discrètement des élèves touchés par une nouvelle règle."},"Tu organises des échanges de notes et aides les élèves à trouver des solutions autorisées. Tu ne deviens pas le visage du mouvement, mais plusieurs personnes savent qu’elles peuvent compter sur toi."]]],["Une porte qui se referme","Couloir interdit","Tu arrives devant un passage qui était accessible quelques jours plus tôt. Une serrure neuve et des traces de pas récentes indiquent que quelqu’un a voulu empêcher les visites. Derrière la porte, aucun bruit ne se fait entendre. Tu peux rechercher une autorisation ou chercher ce qui a motivé la fermeture.",[["Consulter les registres et demander une autorisation","Une limite peut signaler un danger réel.",{"reputation":{"professors":1},"clue":"La fermeture du passage suit un incident consigné sous accès restreint.","journal":"Tu as recherché les raisons d’une fermeture avant d’agir."},"Le registre confirme qu’un incident a eu lieu, mais les détails sont protégés. Tu obtiens l’assurance que la fermeture sera réévaluée. La piste est ralentie, pas effacée."],["Examiner les traces visibles sans toucher à la serrure","Observer n’est pas la même chose que pénétrer.",{"skills":{"Défense":1},"clue":"Les traces indiquent plusieurs passages récents malgré la fermeture officielle.","flags":{"doorFootprints":true},"journal":"Tu as étudié les traces devant un passage fermé."},"Les traces sont plus nombreuses que prévu et ne vont pas toutes dans le même sens. Tu ne peux pas identifier leurs auteurs, mais tu disposes d’un fait concret à comparer aux témoignages."]]],["La tentation du raccourci","Salle d’étude","Un ouvrage ancien décrit une méthode magique puissante, mais avertit que son usage peut laisser des traces sur celui qui l’emploie. Une partie de toi veut obtenir des réponses plus vite. Une autre sait que le pouvoir immédiat peut compliquer les relations et rendre les erreurs plus graves.",[["Étudier les risques sans pratiquer le sort","Comprendre une tentation peut éviter d’y céder aveuglément.",{"flags":{"darkMagicStudied":true},"skills":{"Défense":1},"clue":"Les notes décrivent un coût durable lié à une magie interdite.","journal":"Tu as étudié une magie risquée sans la pratiquer."},"Tu recopies les avertissements et refermes le livre. Les informations ne te rendent pas invulnérable à la tentation, mais tu sais maintenant que les effets ne se limitent pas à l’instant du sort."],["Tenter une version limitée malgré les avertissements","Le gain immédiat peut avoir un prix durable.",{"flags":{"darkMagicUsed":true},"magic":15,"reputation":{"students":-1},"journal":"Tu as utilisé une magie risquée pour obtenir un avantage immédiat."},"Le sort répond avec une facilité troublante. Tu obtiens un indice, mais une sensation froide persiste et tu comprends que tu as franchi une limite. Tu ne peux pas annuler ce choix : tu peux seulement décider de ce que tu en feras ensuite."]]],["Une alliance sous pression","Salle commune","Deux personnes qui te sont chères réclament ton soutien dans des directions opposées. Chacune a de bonnes raisons, et chacune oublie une partie de l’histoire. Choisir un camp rapidement préserverait peut-être un lien, mais risquerait d’abîmer l’autre.",[["Écouter chaque version séparément avant de répondre","Refuser le faux choix entre loyauté et lucidité.",{"relations":{"Harry Potter":1,"Hermione Granger":1},"flags":{"heardBothSides":true},"journal":"Tu as écouté deux versions avant de prendre position."},"Les deux conversations révèlent des informations que personne n’avait partagées en groupe. Tu n’as pas encore décidé qui a raison, mais tu as empêché le conflit de se résumer à une déclaration de loyauté."],["Dire clairement quelle limite tu refuses de franchir","Une position honnête peut déplaire aux deux camps.",{"reputation":{"students":1},"flags":{"setAllianceBoundary":true},"journal":"Tu as posé une limite claire au milieu d’un conflit."},"Ta réponse déçoit ceux qui voulaient un soutien sans condition. Pourtant, tu as rendu tes principes compréhensibles. Les relations qui survivront à cette limite seront peut-être plus solides, même si elles sont moins simples."]]]],[["Le prix d’une information","Bibliothèque","Une personne prétend connaître la suite de ton enquête et propose de te remettre un document en échange d’un service. Son récit contient un détail exact, mais elle refuse de préciser comment elle l’a appris. Tu peux accepter un échange encadré ou refuser de devenir dépendant d’une source opaque.",[["Demander une preuve et fixer des limites précises","Une information utile doit pouvoir être évaluée.",{"clue":"Une source possède des informations exactes mais refuse de révéler leur provenance.","flags":{"sourceBoundaries":true},"journal":"Tu as exigé des limites claires avant d’accepter une information."},"La personne montre un fragment du document, suffisamment pour confirmer qu’elle en possède un. Tu refuses de promettre davantage avant d’avoir vérifié le reste. La négociation reste ouverte, sans dette immédiate."],["Refuser l’échange et chercher une source indépendante","Renoncer à un raccourci peut protéger ton autonomie.",{"skills":{"Sortilèges":1},"reputation":{"professors":1},"journal":"Tu as refusé une information obtenue à des conditions opaques."},"La personne s’éloigne sans insister. Tu perds peut-être une piste rapide, mais tu conserves la liberté de vérifier les faits sans devoir une faveur à quelqu’un dont tu ignores les intentions."]]],["Le cours de défense avancée","Salle d’entraînement","Le professeur vous place dans une situation où la meilleure réponse n’est pas toujours d’attaquer. Il faut protéger un partenaire, reconnaître une feinte et économiser son énergie. Tu peux jouer le rôle de soutien ou tenter de prendre le contrôle de l’exercice.",[["Protéger ton partenaire et annoncer les ouvertures","La coopération peut créer une stratégie plus fiable.",{"skills":{"Défense":2},"relations":{"Neville Londubat":1},"magic":-5,"housePoints":2,"journal":"Tu as privilégié la protection d’un partenaire pendant un exercice avancé."},"Tu annonces les changements de rythme et couvres le côté que ton partenaire ne voit pas. L’exercice n’est pas parfait, mais vous évitez plusieurs erreurs. Le professeur insiste sur la confiance comme compétence, pas comme sentiment abstrait."],["Prendre l’initiative et tenter une combinaison de sorts","L’audace exige de garder une réserve pour se défendre.",{"skills":{"Sortilèges":2},"magic":-12,"health":-2,"journal":"Tu as tenté une combinaison offensive en défense avancée."},"Ta combinaison surprend l’adversaire d’exercice, mais te laisse momentanément sans énergie. Tu réussis l’objectif et apprends pourquoi une attaque doit toujours prévoir la seconde suivante."]]],["Le souvenir qui ne s’efface pas","Tour silencieuse","Tu reviens au souvenir que tu as choisi pour travailler le Patronus. Avec le temps, il a perdu une partie de sa netteté, mais son sens reste présent. Tu peux le laisser évoluer avec ce que tu es devenu ou t’accrocher à la manière exacte dont tu t’en souvenais.",[["Accepter que le souvenir ait changé avec toi","La force d’un souvenir ne dépend pas de son immobilité.",{"patronusStage":1,"flags":{"patronusMemoryEvolved":true},"journal":"Tu as approfondi ton souvenir fondateur pour le Patronus."},"La lumière apparaît un instant plus longtemps. Tu comprends que tu ne dois pas figer le passé pour qu’il t’aide. Il peut continuer à vivre avec toi sans devenir une cage."],["Retrouver les détails concrets du moment","L’attention aux détails peut rendre le souvenir plus accessible.",{"patronusStage":1,"skills":{"Défense":1},"journal":"Tu as travaillé la concentration nécessaire au Patronus."},"Tu reconstruis les sons, les gestes et la sensation de l’instant. La lumière demeure fragile, mais tu peux la rappeler avec davantage de précision. La maîtrise est encore loin, pourtant l’exercice devient moins abstrait."]]],["Une nuit de veille","Infirmerie","Après une journée éprouvante, un camarade reste à l’infirmerie et refuse de parler de ce qui l’a conduit là. Tu peux rester en silence à ses côtés ou lui proposer une aide concrète pour les jours à venir. Tu sais qu’insister pourrait fermer la porte qu’il vient à peine d’entrouvrir.",[["Rester présent sans exiger de confidences","Le soutien n’a pas toujours besoin de mots.",{"relations":{"Harry Potter":1,"Neville Londubat":1},"health":10,"journal":"Tu as accompagné un camarade sans exiger d’explication."},"Le silence s’étire, ponctué par les bruits de l’infirmerie. Avant ton départ, ton camarade te remercie d’être resté. Il ne raconte pas ce qui s’est passé, mais la confiance a gagné un peu de terrain."],["Proposer un plan pratique pour le lendemain","Aider à retrouver une prise sur les choses.",{"relations":{"Hermione Granger":1},"flags":{"offeredPracticalHelp":true},"journal":"Tu as proposé une aide concrète après une journée difficile."},"Vous notez les tâches qui peuvent attendre et celles pour lesquelles il faudra demander de l’aide. Le problème n’a pas disparu, mais il semble moins immense une fois divisé en étapes."]]]],[["Le château en silence","Poudlard","Les couloirs semblent retenir leur souffle. Des élèves qui riaient ensemble se parlent désormais à voix basse, et certaines portes restent fermées sans explication. Tu dois choisir où placer ton attention : protéger les personnes autour de toi ou chercher l’information qui pourrait expliquer ce changement.",[["Organiser un point de rencontre sûr pour les élèves","La protection commence par des gestes concrets.",{"relations":{"Neville Londubat":2,"Harry Potter":1},"reputation":{"students":2},"flags":{"safeMeetingPoint":true},"journal":"Tu as organisé un point de rencontre sûr pour des élèves."},"Le lieu n’est pas parfait, mais chacun sait où retrouver de l’aide. Tu entends plusieurs récits contradictoires et décides de les noter sans répandre les rumeurs. Le groupe devient un peu plus difficile à isoler."],["Reconstituer les événements à partir de sources fiables","Une explication solide peut éviter une panique inutile.",{"skills":{"Sortilèges":1,"Défense":1},"clue":"Plusieurs restrictions récentes partagent la même date de décision.","journal":"Tu as cherché une chronologie fiable des changements au château."},"Les registres et les témoignages dessinent une chronologie. Elle ne répond pas à toutes les questions, mais révèle que plusieurs restrictions ont été décidées en même temps. Tu disposes enfin d’un fil vérifiable."]]],["Les alliés de la dernière heure","Salle commune","Les personnes qui t’ont accompagné au fil des années ne sont pas toutes d’accord sur la marche à suivre. Certaines veulent agir immédiatement, d’autres craignent de perdre ce qu’elles ont réussi à protéger. Tu peux chercher un objectif commun ou demander à chacun ce qu’il refuse de sacrifier.",[["Définir un objectif commun et répartir les rôles","La cohésion ne demande pas que tout le monde pense pareil.",{"relations":{"Harry Potter":1,"Ron Weasley":1,"Hermione Granger":1},"flags":{"alliesCoordinated":true},"journal":"Tu as aidé tes alliés à définir un objectif commun."},"La discussion est tendue, mais chacun repart avec une tâche claire. Les désaccords ne disparaissent pas. Ils cessent simplement de bloquer chaque décision, et c’est déjà une forme de progrès."],["Écouter les limites de chacun avant de décider","Un plan réaliste doit tenir compte des personnes qui le porteront.",{"relations":{"Neville Londubat":1},"reputation":{"students":1},"journal":"Tu as tenu compte des limites de tes alliés avant de choisir."},"Tu découvres que certaines réticences viennent d’expériences que tu ignorais. Le plan sera moins rapide, mais personne n’est forcé de promettre ce qu’il ne peut pas tenir."]]],["Le Patronus prend forme","Cour intérieure","Tu repenses aux souvenirs qui t’ont accompagné depuis tes premières années. Ils ne racontent pas une histoire parfaite : certains sont lumineux, d’autres difficiles. Pourtant, ensemble, ils dessinent ce que tu as choisi de protéger. La magie répond plus clairement qu’avant, mais elle exige encore une décision intérieure : accepter ce que cette forme dit de toi.",[["Accueillir la forme sans chercher à la contrôler","Reconnaître ce que tu es devenu.",{"patronusStage":2,"flags":{"patronusRevealed":true},"journal":"Ton Patronus a enfin révélé sa forme."},"La lumière quitte ta baguette et prend une forme animale argentée. Pendant quelques secondes, elle traverse la cour avec une assurance tranquille avant de se dissiper. Tu n’as pas choisi cette forme comme on choisit un emblème : elle est née de ton parcours."],["Concentrer ta magie sur le souvenir le plus difficile à préserver","Le courage peut venir de ce que tu refuses d’abandonner.",{"patronusStage":2,"skills":{"Défense":1},"flags":{"patronusRevealed":true},"journal":"Tu as révélé ton Patronus en protégeant un souvenir difficile."},"La lumière tremble, puis s’élance. La forme apparaît avec une netteté inattendue et se tourne vers toi avant de disparaître. Tu comprends que ta force ne vient pas d’un passé sans douleur, mais de ce que tu en as fait."]]],["Après la dernière bataille","Grande Salle","Le bruit retombe peu à peu. Les survivants cherchent des visages familiers, les blessés reçoivent de l’aide et les murs portent les traces de ce qui vient de se passer. Il n’existe pas de geste capable de rendre tout intact. Tu peux commencer par retrouver les personnes qui comptent pour toi ou aider ceux qui n’ont personne à chercher.",[["Retrouver tes proches et tenir les promesses faites","Les liens personnels font partie de ce qui mérite d’être sauvé.",{"relations":{"Harry Potter":1,"Ron Weasley":1,"Hermione Granger":1},"flags":{"reunitedWithFriends":true},"health":10,"journal":"Après la bataille, tu as retrouvé les personnes qui comptent pour toi."},"Les retrouvailles sont imparfaites, pleines de questions et de silences. Mais les visages que tu cherchais sont là. Tu sais que la suite demandera du temps, et que les promesses devront maintenant prendre la forme d’actes."],["Aider à organiser les premiers secours et les recherches","Prendre soin des autres peut être une façon de commencer à réparer.",{"reputation":{"students":2,"professors":1},"housePoints":5,"flags":{"helpedAfterBattle":true},"journal":"Tu as aidé les autres dans les heures qui ont suivi la bataille."},"Tu transportes du matériel, transmets des messages et aides à réunir des personnes séparées. Tu ne peux pas tout réparer, mais tu contribues à ce que personne ne soit oublié dans le chaos."]]]]];
EXTRA_SCENES.forEach((group, i) => YEARS[i].push(...group.map(([title,place,text,choices]) => ({title,place,text,choices:choices.map(([label,desc,effect,next])=>({label,desc,effect,next}))}))));

// Chapitres supplémentaires écrits pour cette édition : scènes originales, choix et conséquences persistantes.
const NEW_SCENES = [
[
{title:'La première nuit dans la tour',place:'Salle commune',text:'Le château a fini par se taire, mais le sommeil ne vient pas. Les ombres des rideaux dessinent des formes mouvantes sur les murs. Dans le couloir, quelqu’un semble chercher une porte sans vouloir réveiller les autres. Tu peux intervenir ou observer avant de te mêler de ce qui ne te regarde peut-être pas.',choices:[{label:'Proposer ton aide à voix basse',desc:'La bienveillance peut créer une première alliance.',effect:{relations:{'Neville Londubat':1},reputation:{students:1},flags:{helpedFirstNight:true},journal:'Tu as aidé un élève désorienté lors de ta première nuit.'},next:'L’élève explique qu’il cherche la salle de bain et n’ose pas déranger les préfets. Vous retrouvez le chemin ensemble. Le château paraît moins immense quand on ne le traverse pas seul.'},{label:'Observer le trajet avant de parler',desc:'Comprendre la situation avant d’agir.',effect:{skills:{Sortilèges:1},clue:'Un portrait du couloir change de place quand personne ne le regarde.',flags:{portraitNoticed:true},journal:'Tu as remarqué un détail étrange pendant la première nuit.'},next:'Tu remarques qu’un portrait se trouve légèrement plus loin chaque fois que tu détournes les yeux. Le lendemain, il prétend n’avoir jamais bougé. Tu notes le détail, sans encore savoir s’il compte.'}]},
{title:'Le premier devoir',place:'Salle de classe',text:'Ton premier devoir semble simple jusqu’à ce que tu compares les consignes aux notes prises en classe. Deux élèves affirment que le professeur attend une réponse différente. Tu as le temps de vérifier une seule source avant de rendre ton travail.',choices:[{label:'Reprendre tes notes et vérifier chaque étape',desc:'La méthode demande du temps mais évite les conclusions hâtives.',effect:{skills:{Sortilèges:1},reputation:{professors:1},housePoints:2,flags:{firstHomeworkCareful:true},journal:'Tu as rendu un devoir soigneusement vérifié.'},next:'La réponse n’est pas la plus brillante de la classe, mais chaque étape est justifiée. Le professeur souligne ta rigueur et t’encourage à continuer.'},{label:'Demander à un camarade d’expliquer son raisonnement',desc:'Apprendre ensemble plutôt que recopier une réponse.',effect:{relations:{'Hermione Granger':1,'Ron Weasley':1},flags:{firstHomeworkShared:true},journal:'Tu as comparé ton raisonnement à celui d’un camarade.'},next:'La discussion révèle que vous avez compris des parties différentes de la leçon. En confrontant vos méthodes, vous corrigez chacun une erreur sans simplement reprendre la réponse de l’autre.'}]}],
[
{title:'Une rumeur dans l’escalier',place:'Escaliers mouvants',text:'Une rumeur circule à propos d’un passage qui se serait ouvert près d’un escalier. Les versions divergent : certains parlent d’un raccourci, d’autres d’un piège. Tu peux rechercher l’origine de l’histoire ou suivre les traces avant qu’elles ne disparaissent.',choices:[{label:'Remonter jusqu’à la première personne qui en parle',desc:'Vérifier la source avant de croire la rumeur.',effect:{clue:'La rumeur du passage vient de deux récits qui ne concordent pas.',skills:{Métamorphose:1},reputation:{students:1},journal:'Tu as vérifié l’origine d’une rumeur avant de la relayer.'},next:'La première personne n’a jamais vu le passage : elle répète ce qu’un ami lui a dit. La seconde a bien vu une porte, mais à un autre étage. La piste existe peut-être, mais la rumeur a déformé les faits.'},{label:'Suivre les marques de poussière sur les marches',desc:'Chercher une preuve matérielle.',effect:{clue:'Des marques récentes s’arrêtent devant une tapisserie ancienne.',flags:{stairDustTrail:true},journal:'Tu as suivi des traces matérielles dans les escaliers.'},next:'Les marques s’arrêtent devant une tapisserie qui semble ordinaire. Derrière le tissu, la pierre est plus froide que le mur voisin. Tu n’as pas trouvé de passage ouvert, mais tu tiens une piste vérifiable.'}]},
{title:'Le choix d’un allié',place:'Cour intérieure',text:'Deux camarades se disputent après un exercice raté. Chacun te demande, sans le dire franchement, de prendre son parti. Tu connais seulement une partie de l’histoire ; ta réponse peut apaiser le conflit ou transformer un désaccord en rivalité.',choices:[{label:'Écouter chacun séparément avant de répondre',desc:'Refuser de juger sur une seule version.',effect:{relations:{'Ron Weasley':1,'Hermione Granger':1},reputation:{students:1},flags:{mediatedDispute:true},journal:'Tu as tenté de résoudre un désaccord en écoutant les deux versions.'},next:'Les récits ne coïncident pas sur tous les détails, mais chacun reconnaît sa part d’erreur. Ils ne deviennent pas soudain meilleurs amis ; ils acceptent seulement de reprendre l’exercice sans chercher à humilier l’autre.'},{label:'Défendre la personne qui semble avoir été traitée injustement',desc:'Prendre position même sans tout savoir.',effect:{relations:{'Neville Londubat':1},flags:{tookSideInDispute:true},reputation:{students:-1},journal:'Tu as pris position dans une dispute sans disposer de tous les éléments.'},next:'La personne que tu défends se sent soutenue. L’autre considère que tu as décidé trop vite. Tu pourras revenir sur ton jugement si de nouveaux faits apparaissent, mais la première impression laissera une trace.'}]}],
[
{title:'Les marges d’un registre',place:'Bibliothèque',text:'Un registre d’emprunts mentionne plusieurs ouvrages consultés les mêmes jours, puis une série de pages manquantes. L’indice ne prouve aucun complot : il peut s’agir d’un archivage maladroit. Pour avancer, il faut relier les dates à un autre élément de ton carnet.',choices:[{label:'Comparer les dates aux indices déjà réunis',desc:'Une enquête progresse en reliant les faits, pas en devinant.',effect:{skills:{Sortilèges:1},clue:'Les emprunts du registre précèdent chaque modification des plans de quelques jours.',flags:{archiveDatesCompared:true},journal:'Tu as relié les dates d’un registre à tes autres indices.'},next:'Les dates dessinent une séquence cohérente. Tu ignores encore qui a consulté les livres, mais tu sais désormais quand les changements ont commencé. C’est une question plus précise que celle avec laquelle tu étais entré.'},{label:'Demander l’aide d’une personne qui connaît les archives',desc:'Accepter qu’une expertise extérieure puisse compléter la tienne.',effect:{relations:{'Hermione Granger':1},reputation:{professors:1},flags:{archiveHelpRequested:true},journal:'Tu as demandé de l’aide pour interpréter des archives anciennes.'},next:'Avec une méthode de classement, tu retrouves une référence oubliée. Elle ne livre pas la réponse, mais indique qu’une partie du registre a été déplacée plutôt que détruite.'}]},
{title:'Le prix d’une réponse',place:'Couloir des salles de classe',text:'Un élève te propose un renseignement utile en échange d’une faveur future. Il ne précise ni la nature de la faveur ni le moment où il viendra la réclamer. Tu peux négocier des limites, refuser ou accepter le risque.',choices:[{label:'Accepter uniquement avec une faveur définie à l’avance',desc:'La confiance a besoin de limites explicites.',effect:{flags:{boundedFavor:true},clue:'Un élève affirme qu’un registre a été déplacé vers une salle de rangement.',journal:'Tu as négocié des conditions claires avant d’accepter une information.'},next:'Après quelques échanges, vous convenez d’un service simple et limité. L’information reste à vérifier, mais tu n’as pas accepté une dette sans contours.'},{label:'Refuser et chercher une source indépendante',desc:'Renoncer au raccourci pour garder ton autonomie.',effect:{skills:{Défense:1},reputation:{professors:1},flags:{refusedOpaqueDeal:true},journal:'Tu as refusé une information obtenue à des conditions opaques.'},next:'La piste prendra plus de temps à vérifier. En revanche, personne ne pourra utiliser cette conversation pour te pousser à agir contre ton jugement.'}]}],
[
{title:'Le devoir qui divise',place:'Salle de classe',text:'Le professeur demande une analyse d’un sort dont les usages peuvent protéger ou contraindre. La classe se divise entre ceux qui jugent l’intention suffisante et ceux qui insistent sur les conséquences. Ton devoir doit défendre une position sans ignorer ses limites.',choices:[{label:'Défendre une règle qui tient compte du contexte et des conséquences',desc:'Une bonne règle doit résister aux cas difficiles.',effect:{skills:{Défense:1},reputation:{professors:1},housePoints:3,flags:{nuancedEthicsEssay:true},journal:'Tu as défendu une approche nuancée des usages de la magie.'},next:'Le professeur relève que ton argumentation distingue l’intention de l’effet produit. Il te demande de conserver cette prudence lorsque tu seras tenté de justifier un résultat par une bonne intention.'},{label:'Soutenir qu’une règle claire protège mieux les plus vulnérables',desc:'La cohérence peut empêcher les abus.',effect:{skills:{Sortilèges:1},reputation:{professors:1},flags:{clearRulesEssay:true},journal:'Tu as défendu des limites claires dans l’usage de la magie.'},next:'Ta réponse convainc plusieurs élèves qui craignent que les exceptions servent toujours les plus puissants. Tu comprends cependant qu’une règle devra aussi être appliquée avec discernement.'}]},
{title:'Une invitation à Pré-au-Lard',place:'Pré-au-Lard',text:'Lors d’une sortie autorisée, un groupe veut se rendre directement aux boutiques. Un camarade te parle d’une lettre qu’il n’arrive pas à comprendre et te demande quelques minutes avant de rejoindre les autres. Le temps est limité, mais le choix n’est pas forcément irréversible.',choices:[{label:'Prendre le temps de lire la lettre avec lui',desc:'Une relation peut compter davantage qu’un programme parfait.',effect:{relations:{'Harry Potter':1,'Neville Londubat':1},clue:'La lettre contient une date et un lieu qui ne correspondent pas au récit oral.',flags:{letterCompared:true},journal:'Tu as aidé un camarade à examiner une lettre mystérieuse.'},next:'La lettre ne révèle pas une vérité spectaculaire, mais elle contredit un détail important du récit. Vous décidez de vérifier la date avant d’en parler à qui que ce soit.'},{label:'Rejoindre les boutiques et chercher un ouvrage de référence',desc:'Une source indépendante peut aider à comprendre le document.',effect:{galleons:-2,inventoryAdd:'Guide des symboles anciens',skills:{Sortilèges:1},journal:'Tu as acheté un guide pour étudier les symboles anciens.'},next:'Le guide n’offre pas de traduction immédiate, mais plusieurs symboles ressemblent à ceux que tu as notés. Tu gardes le livre pour les comparer plus tard.'}]}],
[
{title:'Le cercle de confiance',place:'Salle commune',text:'Les rumeurs ont rendu les conversations plus prudentes. Un petit groupe veut partager des informations, mais certains craignent que tout soit répété à d’autres élèves. Tu dois décider comment organiser l’échange sans promettre une confidentialité impossible.',choices:[{label:'Établir des règles de vérification et de discrétion',desc:'Partager des faits sans transformer les soupçons en certitudes.',effect:{reputation:{students:2},relations:{'Hermione Granger':1},flags:{trustCircle:true},journal:'Tu as aidé à organiser un échange prudent d’informations.'},next:'Le groupe accepte de séparer les faits observés des suppositions. Personne ne promet le silence absolu, mais chacun s’engage à ne pas présenter une rumeur comme une preuve.'},{label:'Garder les informations pour toi jusqu’à leur confirmation',desc:'Protéger les autres du poids d’une hypothèse fragile.',effect:{skills:{Métamorphose:1},clue:'Une information non confirmée doit être vérifiée par une seconde source.',flags:{keptRumorPrivate:true},journal:'Tu as retenu une information tant qu’elle n’était pas confirmée.'},next:'Tu avances plus lentement, mais tu évites de déclencher une réaction sur la base d’un témoignage incertain. Tu cherches maintenant une seconde source.'}]},
{title:'Le prix d’une promesse',place:'Parc et lac',text:'Une personne que tu apprécies te demande de promettre que tu l’aideras, quoi qu’il arrive. Tu sais qu’un engagement absolu peut devenir dangereux si tu découvres plus tard que l’action demandée ferait du mal à quelqu’un. Comment répondre sans abandonner cette relation ?',choices:[{label:'Promettre de rester présent, sans promettre d’obéir à tout',desc:'La loyauté n’efface pas le discernement.',effect:{relations:{'Harry Potter':1,'Ron Weasley':1,'Hermione Granger':1},flags:{promiseWithBoundaries:true},journal:'Tu as formulé une promesse sincère avec des limites claires.'},next:'La réponse déçoit un peu au début, mais elle est honnête. Tu promets d’écouter, de chercher une solution et de ne pas abandonner la personne — pas de suivre aveuglément chaque demande.'},{label:'Accepter la promesse pour rassurer ton ami maintenant',desc:'Le réconfort immédiat peut créer une obligation difficile.',effect:{relations:{'Harry Potter':2},flags:{absolutePromise:true},journal:'Tu as fait une promesse absolue pour rassurer un ami.'},next:'Le soulagement est immédiat. Tu sais pourtant que cette promesse pourrait revenir au moment où les choix deviendront plus complexes. Il faudra alors trouver comment rester fidèle à l’intention sans ignorer les conséquences.'}]}],
[
{title:'Le carnet des décisions',place:'Bibliothèque',text:'En relisant tes notes, tu découvres que deux décisions prises à plusieurs mois d’intervalle se contredisent en apparence. Tu peux effacer la première interprétation ou accepter que ta compréhension ait évolué. Le carnet n’est pas un tribunal : il doit t’aider à voir les changements.',choices:[{label:'Écrire ce qui a changé dans ton raisonnement',desc:'Reconnaître une évolution plutôt que réécrire le passé.',effect:{skills:{Sortilèges:1},flags:{reviewedOwnChoices:true},journal:'Tu as relu tes propres décisions et noté ce qui avait changé.'},next:'Tu conserves les deux versions et ajoutes ce que tu sais désormais. Le chemin parcouru devient visible, y compris les moments où tu avais tort.'},{label:'Chercher le fait qui permet de départager les deux interprétations',desc:'Une contradiction peut révéler une information manquante.',effect:{clue:'Une même action peut avoir eu des effets différents selon le contexte.',flags:{contextContradiction:true},journal:'Tu as recherché le contexte derrière une contradiction.'},next:'Tu retrouves un détail que tu avais ignoré. Les décisions n’étaient pas identiques : les personnes concernées et les risques avaient changé. Le contexte explique une partie de la contradiction, pas tout.'}]},
{title:'Le dernier entraînement',place:'Terrain de Quidditch',text:'La saison approche de son moment décisif. L’équipe est fatiguée et les stratégies habituelles deviennent prévisibles. Le capitaine te demande de choisir entre une action spectaculaire et une tactique plus patiente qui laisse à chacun un rôle.',choices:[{label:'Construire une action collective en plusieurs passes',desc:'La coordination peut compenser une faiblesse individuelle.',effect:{quidditch:{trained:1},relations:{'Ron Weasley':1},reputation:{students:1},housePoints:2,flags:{teamStrategy:true},journal:'Tu as privilégié la coordination lors du dernier entraînement.'},next:'La combinaison n’est pas spectaculaire, mais chaque joueur sait où se placer. L’équipe progresse parce que personne n’essaie de tout faire seul.'},{label:'Travailler une action individuelle difficile',desc:'Prendre un risque mesuré pour surprendre l’adversaire.',effect:{quidditch:{trained:2},skills:{Défense:1},flags:{soloQuidditchMove:true},journal:'Tu as travaillé une action individuelle exigeante au Quidditch.'},next:'Tu rates d’abord le geste, puis ajustes ton approche. La manœuvre reste risquée, mais elle peut surprendre une équipe qui s’attend à voir toujours la même stratégie.'}]}],
[
{title:'La vérité et ses témoins',place:'Salle des archives',text:'À l’approche de la fin, plusieurs témoignages semblent confirmer la même hypothèse. Pourtant, leurs auteurs n’ont pas observé les événements au même moment. Tu dois décider si tu présentes une conclusion immédiate ou si tu consacres encore du temps à distinguer ce qui est certain de ce qui reste probable.',choices:[{label:'Présenter uniquement les faits corroborés',desc:'Une conclusion plus étroite peut être plus solide.',effect:{reputation:{professors:2},skills:{Défense:1},flags:{truthCarefullyPresented:true},journal:'Tu as distingué les faits confirmés des hypothèses dans ton enquête finale.'},next:'Ta conclusion est moins spectaculaire que certaines rumeurs, mais chaque affirmation peut être reliée à une source. Les personnes qui t’écoutent peuvent contester ton interprétation sans pouvoir dire que tu as inventé les faits.'},{label:'Exposer l’hypothèse complète en signalant ses incertitudes',desc:'Une piste ambitieuse peut aider les autres à poursuivre l’enquête.',effect:{clue:'La dernière hypothèse relie plusieurs indices mais demande encore une confirmation.',flags:{fullHypothesisShared:true},journal:'Tu as partagé une hypothèse complète en exposant ses incertitudes.'},next:'Ton hypothèse ouvre une nouvelle discussion. Certains la trouvent convaincante, d’autres demandent des preuves supplémentaires. Tu as donné une direction à l’enquête sans prétendre que tout est résolu.'}]},
{title:'Ce que tu transmets',place:'Grande Salle',text:'Les années passées à Poudlard t’ont appris des sorts, des méthodes et des choses plus difficiles à mesurer. Un nouvel élève te demande quel conseil il devrait garder avant de faire ses propres choix. Tu pourrais lui transmettre une règle, une question ou le souvenir d’une erreur.',choices:[{label:'Lui apprendre à demander de l’aide sans renoncer à son jugement',desc:'L’indépendance et l’entraide peuvent se renforcer.',effect:{relations:{'Neville Londubat':1},reputation:{students:2},flags:{mentoredStudent:true},journal:'Tu as transmis à un nouvel élève un conseil issu de ton parcours.'},next:'Tu ne lui donnes pas une réponse valable pour toutes les situations. Tu lui apprends plutôt à reconnaître le moment où une autre perspective peut éviter une erreur.'},{label:'Lui raconter une erreur dont tu as appris quelque chose',desc:'Une expérience honnête peut être plus utile qu’un discours parfait.',effect:{reputation:{students:1},flags:{sharedMistake:true},journal:'Tu as partagé une erreur personnelle pour aider un nouvel élève.'},next:'Ton récit n’efface pas l’erreur, et c’est précisément ce qui le rend utile. L’élève repart avec l’idée qu’un mauvais choix peut laisser une trace sans définir toute une vie.'}]}]
];
NEW_SCENES.forEach((group,i)=>YEARS[i].push(...group));

const YEAR_NAMES=['La première étincelle','Les secrets des couloirs','Les archives oubliées','Le prix des vérités','Les ombres grandissantes','Le choix de la lumière','La dernière page'];
const LOCATIONS=[{name:'Grande Salle',icon:'♧',desc:'Les quatre tables, les annonces et les moments qui rassemblent toute l’école.',unlock:1},{name:'Bibliothèque',icon:'▤',desc:'Des ouvrages anciens, des archives et des pistes à recouper.',unlock:1},{name:'Salle de classe',icon:'✳',desc:'Cours, entraînements et exercices de magie.',unlock:1},{name:'Salle commune',icon:'⌂',desc:'Un refuge propre à ta maison où les relations évoluent.',unlock:1},{name:'Parc et lac',icon:'♧',desc:'Un espace pour respirer, discuter et observer des détails inattendus.',unlock:1},{name:'Terrain de Quidditch',icon:'⚯',desc:'Entraînement, tactique et esprit d’équipe.',unlock:1},{name:'Couloirs interdits',icon:'⌖',desc:'Des passages à explorer avec prudence.',unlock:2},{name:'Forêt interdite',icon:'♜',desc:'Un lieu dangereux où l’observation compte autant que le courage.',unlock:3},{name:'Pré-au-Lard',icon:'✧',desc:'Boutiques, rencontres et sorties selon l’âge et le calendrier.',unlock:3}];
const SPELLS=[{name:'Lumos',desc:'Éclaire les endroits sombres.',cost:3,unlock:1},{name:'Nox',desc:'Éteint la lumière de ta baguette.',cost:0,unlock:1},{name:'Expelliarmus',desc:'Désarme un adversaire lors d’un duel.',cost:12,unlock:1},{name:'Protego',desc:'Dresse une défense magique.',cost:10,unlock:1},{name:'Reparo',desc:'Répare certains objets endommagés.',cost:8,unlock:2},{name:'Accio',desc:'Attire vers toi un objet accessible.',cost:12,unlock:2},{name:'Expecto Patronum',desc:'Un sort avancé nourri par un souvenir véritable.',cost:30,unlock:5},{name:'Stupefix',desc:'Neutralise temporairement une cible.',cost:15,unlock:3}];
function setTheme(){const h=HOUSES[S.character.house]||{accent:'#9f303c',accent2:'#d6b875'};document.documentElement.style.setProperty('--accent',h.accent);document.documentElement.style.setProperty('--accent2',h.accent2);document.documentElement.style.setProperty('--glow',h.accent2);document.documentElement.style.setProperty('--fontScale',S.settings.fontScale||1);document.documentElement.style.setProperty('--reading',(S.settings.reading||760)+'px');if(S.settings.contrast)document.body.style.filter='contrast(1.15)';else document.body.style.filter='';if(S.settings.reduced)document.documentElement.style.setProperty('scroll-behavior','auto');}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
const PAGE_FILES={home:'index.html',create:'personnage.html',sorting:'repartition.html',story:'histoire.html',ending:'epilogue.html',map:'exploration.html',activities:'activites.html',journal:'journal.html',profile:'profil.html',relations:'relations.html',spells:'sorts.html',inventory:'inventaire.html',saves:'sauvegardes.html',settings:'parametres.html'};
function saveSession(){try{localStorage.setItem('dp_session',JSON.stringify(S))}catch(e){console.warn('Session non conservée',e)}}
function navigate(page){S.page=page;saveSession();const file=PAGE_FILES[page]||'index.html';const current=location.pathname.split('/').pop()||'index.html';if(current!==file){location.href=file;return}render();window.scrollTo({top:0,behavior:S.settings.reduced?'auto':'smooth'});}
function navActive(){document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.page===S.page))}
function shellTitle(eyebrow,title,sub=''){return `<div class="content"><div class="eyebrow">${eyebrow}</div><h1 class="title">${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>`}
function home(){if(!S.started)return `${shellTitle('Bienvenue dans ton histoire','Harry Potter — <em>Destin de Poudlard</em>','Une aventure narrative où chaque promesse, chaque découverte et chaque décision contribue à écrire ton propre destin.')}
<div class="content wide"><div class="hero"><div class="eyebrow">Année ${S.year} · ${esc(S.character.house||'Poudlard')}</div><h1 class="title">Ta chronique <em>continue.</em></h1><p class="subtitle">${esc(S.character.name)}, le château garde la mémoire de tes choix. La prochaine page t’attend.</p><div class="btnrow" style="justify-content:center"><button class="btn primary" onclick="navigate('story')">Reprendre l’histoire →</button><button class="btn" onclick="navigate('journal')">Ouvrir le journal</button></div></div><div class="statrow">${stat('Année',S.year+'/7')}${stat('Santé',S.health+'%')}${stat('Énergie magique',S.magic+'%')}${stat('Gallions',''+S.galleons)}</div><div class="grid2"><div class="card"><div class="eyebrow">Chapitre en cours</div><h2>${esc(currentScene()?.title||'À découvrir')}</h2><p class="muted small">${esc(currentScene()?.place||'Poudlard')}</p><button class="btn primary" onclick="navigate('story')">Poursuivre →</button></div><div class="card"><div class="eyebrow">Chronique personnelle</div><h2>${S.journal.length} souvenir${S.journal.length===1?'':'s'} consigné${S.journal.length===1?'':'s'}</h2><p class="muted">Tes découvertes, promesses et décisions importantes sont conservées dans ton journal.</p><button class="btn" onclick="navigate('journal')">Relire la chronique</button></div></div></div>`;
return `<div class="content wide"><div class="hero"><div class="eyebrow">Une aventure narrative · Septembre 1991</div><h1 class="title">Harry Potter<br><em>Destin de Poudlard</em></h1><p class="subtitle">Il existe des histoires que l’on reçoit, et d’autres que l’on choisit. Ta lettre est arrivée. Le reste t’appartient.</p><div class="btnrow" style="justify-content:center"><button class="btn gold" onclick="startCreation()">✧ Commencer l’aventure</button><button class="btn" onclick="navigate('saves')">Charger une sauvegarde</button></div><p class="small muted" style="margin-top:20px">Une chronique magique, façonnée par tes choix.</p></div><div class="houses"><div class="house" style="--house:#d6b875"><span class="crest">♌</span><strong>Gryffondor</strong><small>Courage · Audace</small></div><div class="house" style="--house:#7fc4a5"><span class="crest">♜</span><strong>Serpentard</strong><small>Ambition · Ingéniosité</small></div><div class="house" style="--house:#8db5ed"><span class="crest">✧</span><strong>Serdaigle</strong><small>Curiosité · Esprit</small></div><div class="house" style="--house:#e2c65c"><span class="crest">❖</span><strong>Poufsouffle</strong><small>Loyauté · Justice</small></div></div><div class="grid2" style="margin-top:18px"><div class="card slim"><div class="eyebrow">Ton personnage</div><h3>Une histoire qui t’appartient</h3><p class="muted small">Origines libres, personnalité évolutive, baguette personnalisée et relations qui changent au fil des années.</p></div><div class="card slim"><div class="eyebrow">Tes décisions</div><h3>Des conséquences durables</h3><p class="muted small">Les secrets, les alliances et les choix importants peuvent modifier des événements bien plus tard.</p></div></div><div class="notice">Cette création est un fan project non officiel. Les dialogues et scènes sont originaux et ne reproduisent pas les textes des livres ou des films.</div></div>`}
function stat(label,value){return `<div class="stat"><div class="label">${label}</div><strong>${value}</strong></div>`}
function startCreation(){const slots=getSlots();let target=slots.findIndex(x=>!x);if(target<0){const answer=prompt('Tes cinq emplacements sont occupés. Quel emplacement remplacer ? Saisis un numéro de 1 à 5, ou annule pour revenir.');if(answer===null||answer.trim()==='')return;target=Number(answer)-1;if(!Number.isInteger(target)||target<0||target>4){toast('Numéro invalide : choisis un emplacement de 1 à 5.');return}if(!confirm(`L’emplacement ${target+1} sera remplacé par cette nouvelle aventure. Continuer ?`))return}activeSlot=target;localStorage.setItem('dp_active',String(activeSlot));const settings={...S.settings};S={...initialState(),settings};S.started=false;S.setupStep=0;S.page='create';S.quiz={};navigate('create')}
function createPage(){const c=S.character;const step=S.setupStep;let body='';if(step===0){body=`<div class="formgrid"><div class="field"><label for="cname">Nom et prénom</label><input id="cname" maxlength="40" placeholder="Le nom de ton personnage" value="${esc(c.name)}"></div><div class="field"><label for="pronouns">Pronoms (facultatif)</label><select id="pronouns"><option value="" ${!c.pronouns?'selected':''}>Ne pas préciser</option><option ${c.pronouns==='il/lui'?'selected':''}>il/lui</option><option ${c.pronouns==='elle'?'selected':''}>elle</option><option ${c.pronouns==='iel'?'selected':''}>iel</option></select></div><div class="field"><label for="appearance">Apparence (description libre)</label><textarea id="appearance" placeholder="Quelques mots pour décrire ton personnage…">${esc(c.appearance)}</textarea></div><div class="field"><label for="personality">Tempérament actuel</label><select id="personality"><option value="">À découvrir en jouant</option>${['Réfléchi','Audacieux','Curieux','Bienveillant','Indépendant','Ambitieux','Réservé','Spontané'].map(x=>`<option ${c.personality===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`}else if(step===1){body=`<div class="field"><label for="family">Origines familiales</label><select id="family"><option value="">Choisir librement</option>${['Famille de sorciers','Famille mêlant sorciers et non-sorciers','Famille non magique','Origines mystérieuses','Une histoire que je définis moi-même'].map(x=>`<option ${c.family===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="childhood">Ton enfance</label><textarea id="childhood" placeholder="Les souvenirs qui t’ont construit…">${esc(c.childhood)}</textarea></div><div class="field"><label for="ambition">Ce que tu espères devenir</label><input id="ambition" value="${esc(c.ambition)}" placeholder="Une ambition, même encore floue"></div><div class="field"><label for="secret">Un secret (facultatif)</label><textarea id="secret" placeholder="Un souvenir, une promesse ou une question sans réponse…">${esc(c.secret)}</textarea></div>`}else if(step===2){body=`<div class="formgrid"><div class="field"><label for="qualities">Une qualité</label><select id="qualities">${['Courage','Curiosité','Loyauté','Persévérance','Ingéniosité','Empathie'].map(x=>`<option ${c.qualities[0]===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="flaws">Un défaut</label><select id="flaws">${['Impatience','Fierté','Méfiance','Distraction','Entêtement','Peur de décevoir'].map(x=>`<option ${c.flaws[0]===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="animal">Ton animal</label><select id="animal">${['Hibou','Chat','Crapaud'].map(x=>`<option ${c.animal===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="wood">Bois de la baguette</label><select id="wood">${['Houx','Chêne','Saule','If','Érable','Frêne','Cerisier','Bois à découvrir'].map(x=>`<option ${c.wood===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="core">Cœur</label><select id="core">${['Plume de phénix','Crin de licorne','Fibre de cœur de dragon','À découvrir'].map(x=>`<option ${c.core===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="length">Longueur</label><select id="length">${['9 pouces','10 pouces','11 pouces','12 pouces','13 pouces','À découvrir'].map(x=>`<option ${c.length===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="flexibility">Souplesse</label><select id="flexibility">${['Souple','Flexible','Rigide','Très flexible','À découvrir'].map(x=>`<option ${c.flexibility===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`}else{body=`<div class="card slim"><div class="eyebrow">Avant la répartition</div><h2>${esc(c.name||'Ton personnage')}</h2><p class="muted">${esc(c.appearance||'Ton apparence sera révélée au fil de l’histoire.')}</p><div class="divider"></div><p><strong>Origines :</strong> ${esc(c.family||'À définir au fil du récit')}</p><p><strong>Personnalité :</strong> ${esc(c.personality||'Évolutive')}</p><p><strong>Qualité :</strong> ${esc(c.qualities[0]||'À découvrir')} · <strong>Défaut :</strong> ${esc(c.flaws[0]||'À découvrir')}</p><p><strong>Baguette :</strong> ${esc(c.wood||'À découvrir')}, ${esc(c.core||'cœur à découvrir')}</p><p><strong>Compagnon :</strong> ${esc(c.animal||'À choisir')}</p><p><strong>Ambition :</strong> ${esc(c.ambition||'Elle se précisera au fil des années.')}</p></div><div class="notice">La maison sera déterminée par tes réponses au Choixpeau, jamais par tes origines.</div>`}
return `${shellTitle('Création du personnage',`Étape ${step+1} <em>sur 4</em>`,'Construis ton personnage à ton rythme. Tu pourras découvrir qui il devient au fil de l’histoire.')}<div class="content"><div class="progress"><span style="width:${(step+1)*25}%"></span></div><div class="card" style="margin-top:18px"><h2>${['Identité et apparence','Famille et souvenirs','Qualités et objets','Récapitulatif'][step]}</h2>${body}<div class="btnrow"><button class="btn" onclick="createBack()" ${step===0?'disabled':''}>← Retour</button><button class="btn primary" onclick="createNext()">${step===3?'Passer au Choixpeau':'Continuer →'}</button></div></div></div>`}
function createBack(){if(S.setupStep>0)S.setupStep--;render()}
function createNext(){const step=S.setupStep,c=S.character;if(step===0){c.name=$('cname').value.trim();if(!c.name){toast('Donne un nom à ton personnage pour continuer.');$('cname').focus();return}c.pronouns=$('pronouns').value;c.appearance=$('appearance').value.trim();c.personality=$('personality').value;}if(step===1){c.family=$('family').value;c.childhood=$('childhood').value.trim();c.ambition=$('ambition').value.trim();c.secret=$('secret').value.trim()}if(step===2){c.qualities=[$('qualities').value];c.flaws=[$('flaws').value];c.animal=$('animal').value;c.wood=$('wood').value;c.core=$('core').value;c.length=$('length').value;c.flexibility=$('flexibility').value}if(step<3){S.setupStep++;render()}else{S.page='sorting';S.quiz={};navigate('sorting')}}
const QUIZ=[{q:'Face à un problème inconnu, ton premier réflexe est…',a:[['Gryffondor','Agir, même si la peur est présente.'],['Serpentard','Chercher le levier qui permettra d’avancer.'],['Serdaigle','Comprendre comment le problème fonctionne.'],['Poufsouffle','Voir qui pourrait avoir besoin d’aide.']]},{q:'Quelle qualité admires-tu le plus ?',a:[['Gryffondor','Le courage de défendre ce qui compte.'],['Serpentard','La détermination à atteindre un but.'],['Serdaigle','L’esprit ouvert et la curiosité.'],['Poufsouffle','La loyauté qui tient dans la durée.']]},{q:'Un ami commet une erreur importante. Tu…',a:[['Gryffondor','L’aides à affronter la situation.'],['Serpentard','Cherches la meilleure stratégie pour réparer.'],['Serdaigle','Essaies d’abord de comprendre ce qui s’est passé.'],['Poufsouffle','Reste à ses côtés tout en étant honnête.']]},{q:'Que souhaites-tu laisser derrière toi ?',a:[['Gryffondor','La preuve que l’on peut agir malgré les risques.'],['Serpentard','Une réalisation qui n’aurait pas existé sans toi.'],['Serdaigle','Des découvertes qui ouvrent de nouvelles voies.'],['Poufsouffle','Des liens et une confiance durables.']]}];
function sorting(){let total=QUIZ.length;return `${shellTitle('La cérémonie de répartition','Écoute <em>le Choixpeau</em>','Il ne cherche pas à décider qui tu es. Il écoute ce que tu choisis de valoriser.') }<div class="content">${QUIZ.map((q,i)=>`<div class="card"><div class="eyebrow">Question ${i+1} / ${total}</div><h2>${q.q}</h2><div class="choice-list">${q.a.map(([h,t])=>`<button class="choice" onclick="answerQuiz(${i},'${h}')"><span class="choice-mark">${S.quiz[i]===h?'✓':'✧'}</span><span><strong>${h}</strong><small>${t}</small></span></button>`).join('')}</div></div>`).join('')}<div class="btnrow"><button class="btn primary" onclick="finishSorting()">Découvrir ma maison →</button></div></div>`}
function answerQuiz(i,h){S.quiz[i]=h;render()}
function finishSorting(){if(Object.keys(S.quiz).length<QUIZ.length){toast('Réponds aux quatre questions pour entendre le Choixpeau.');return}let scores={Gryffondor:0,Serpentard:0,Serdaigle:0,Poufsouffle:0};Object.values(S.quiz).forEach(h=>scores[h]++);let max=Math.max(...Object.values(scores));let tied=Object.keys(scores).filter(h=>scores[h]===max);let house=tied[0];if(tied.length>1){const personality=S.character.personality;const map={'Audacieux':'Gryffondor','Ambitieux':'Serpentard','Curieux':'Serdaigle','Bienveillant':'Poufsouffle','Réfléchi':'Serdaigle','Indépendant':'Serpentard','Réservé':'Poufsouffle','Spontané':'Gryffondor'};if(tied.includes(map[personality]))house=map[personality]}S.character.house=house;S.started=true;S.page='story';S.year=1;S.chapter=0;S.scene=0;S.journal.push(`Septembre 1991 — ${S.character.name} a été réparti à ${house}.`);S.quests.push('Comprendre les mystères qui entourent les premiers jours à Poudlard');S.reputation.house=1;setTheme();navigate('story');toast(`Bienvenue à ${house} !`)}
function currentScene(){const y=Math.min(6,Math.max(0,S.year-1));return YEARS[y][Math.min(S.chapter,YEARS[y].length-1)]}
function currentSeason(scene=currentScene()){const t=(scene?.title||'').toLowerCase();if(t.includes('noël')||t.includes('hiver')||t.includes('fêtes'))return 'Hiver';if(t.includes('été')||t.includes('vacances'))return 'Vacances';if(t.includes('printemps'))return 'Printemps';if(t.includes('examens')||t.includes('dernière leçon'))return 'Examens';return S.chapter<2?'Automne':'Printemps'}
function contextualNarration(){const house=S.character.house;const lines={Gryffondor:'Les couleurs rouges et or de ta maison te rappellent que le courage ne consiste pas à ignorer le danger, mais à choisir ce que tu en fais.',Serpentard:'Dans le calme de ta maison, tu as appris à regarder les intentions autant que les paroles : une stratégie peut protéger comme elle peut isoler.',Serdaigle:'Ton regard cherche les détails qui résistent aux explications faciles. Une bonne question peut parfois ouvrir plus de portes qu’un sort.',Poufsouffle:'Tu sais que les promesses se mesurent aux actes répétés. Les liens que tu entretiens peuvent devenir une force inattendue.'};let extra=lines[house]||'';if((S.relations['Harry Potter']||0)>=2)extra+=' Harry te considère désormais comme une personne sur laquelle il peut compter.';if((S.relations['Hermione Granger']||0)>=2)extra+=' Hermione partage plus volontiers ses hypothèses avec toi.';if((S.relations['Ron Weasley']||0)>=2)extra+=' Ron se montre plus à l’aise pour te confier ses doutes.';if(S.flags.darkMagicUsed)extra+=' Une décision liée à une magie risquée continue de peser sur ta manière d’aborder les situations dangereuses.';if(S.clues.length>=3)extra+=' Les indices que tu as réunis forment peu à peu un réseau de pistes, mais toutes ne sont pas encore fiables.';return extra}
function story(){if(!S.started)return `${shellTitle('Ton aventure','La première page <em>t’attend</em>','Crée ton personnage pour commencer la chronique.')}<div class="content card"><p class="muted">Aucune aventure active pour le moment.</p><button class="btn primary" onclick="startCreation()">Créer mon personnage →</button></div>`;const scene=currentScene();const house=HOUSES[S.character.house]||HOUSES.Gryffondor;const patronus=S.patronusStage>=3?'La silhouette argentée se dessine plus nettement.':S.patronusStage===2?'La lumière répond quelques instants à ton souvenir.':S.patronusStage===1?'Une lueur argentée frémit, fragile mais réelle.':'Le Patronus reste encore à découvrir.';return `<div class="content"><div class="scene-top"><span class="pill">Année ${S.year} · ${esc(YEAR_NAMES[S.year-1])} · ${esc(currentSeason(scene))}</span><span class="pill">${esc(scene.place)}</span></div><div class="eyebrow">Chapitre ${S.chapter+1} · Chronique vivante</div><h1 class="chapter-title">${esc(scene.title)}</h1><div class="card"><div class="story-copy">${esc(scene.text)}\n\n${esc(contextualNarration())}</div><div class="ornament">✧</div><div class="eyebrow">Que fais-tu ?</div><div class="choice-list" style="margin-top:12px">${scene.choices.map((ch,i)=>`<button class="choice" onclick="choose(${i})"><span class="choice-mark">${String.fromCharCode(65+i)}</span><span><strong>${esc(ch.label)}</strong><small>${esc(ch.desc)}</small></span></button>`).join('')}</div></div><div class="story-footer"><span class="muted small">Les conséquences ne sont pas toujours immédiates.</span><button class="btn" onclick="showModal('Chronique','${esc(patronus)}')">✧ État du Patronus</button></div><div class="notice">Ta maison : ${house.crest} ${esc(S.character.house)} · Tes actions peuvent modifier les relations, les compétences et les événements à venir.</div></div>`}
function applyEffect(effect){if(effect.relations)Object.entries(effect.relations).forEach(([k,v])=>S.relations[k]=Math.max(-5,Math.min(10,(S.relations[k]||0)+v)));if(effect.skills)Object.entries(effect.skills).forEach(([k,v])=>S.skills[k]=(S.skills[k]||0)+v);if(effect.reputation)Object.entries(effect.reputation).forEach(([k,v])=>S.reputation[k]=Math.max(-10,Math.min(10,(S.reputation[k]||0)+v)));if(effect.flags)Object.assign(S.flags,effect.flags);if(effect.galleons)S.galleons=Math.max(0,S.galleons+effect.galleons);if(effect.health)S.health=Math.max(1,Math.min(100,S.health+effect.health));if(effect.magic)S.magic=Math.max(0,Math.min(100,S.magic+effect.magic));if(effect.housePoints){S.housePoints+=effect.housePoints;S.houseCup+=effect.housePoints}if(effect.patronusStage)S.patronusStage=Math.min(3,S.patronusStage+effect.patronusStage);if(S.patronusStage>=3&&(!S.character.patronus||S.character.patronus==='Inconnu'))S.character.patronus=derivePatronus();if(effect.clue)S.clues.push(effect.clue);if(effect.inventoryAdd)S.inventory.push(effect.inventoryAdd);if(effect.quidditch)Object.entries(effect.quidditch).forEach(([k,v])=>S.quidditch[k]=(S.quidditch[k]||0)+v);if(effect.journal)S.journal.push(`Année ${S.year} — ${effect.journal}`)}
function choose(i){const scene=currentScene(),ch=scene?.choices?.[i];if(!scene||!ch)return;const sceneKey=`scene${S.year}-${S.chapter}`;if(S.flags[sceneKey]){toast('Cette scène a déjà été résolue.');return}applyEffect(ch.effect||{});S.choices.push({year:S.year,chapter:S.chapter,title:scene.title,choice:ch.label});S.flags[sceneKey]=true;autoSave();showModal('Les conséquences de ton choix',`${ch.next}<br><br><span class="muted small">Ta décision est conservée dans ta chronique.</span>`,()=>advanceScene());}
function advanceScene(){const max=YEARS[S.year-1].length;if(S.chapter<max-1){S.chapter++;S.health=Math.min(100,S.health+5);S.magic=Math.min(100,S.magic+10)}else if(S.year<7){S.journal.push(`Fin de la ${S.year}${S.year===1?'re':'e'} année — les vacances commencent, et les conséquences de tes décisions voyagent avec toi.`);S.year++;S.chapter=0;S.health=100;S.magic=100;S.galleons+=8;S.calendar.season='Automne';S.calendar.week=1;S.journal.push(`Vacances d’été — ${S.character.name} prend le temps de retrouver ses proches et de réfléchir à l’année écoulée.`);S.quests.push(`Découvrir les secrets de la ${S.year}${S.year===1?'re':'e'} année`);toast(`Année ${S.year} : une nouvelle page commence.`)}else{S.page='ending';navigate('ending');return}S.scene++;autoSave();navigate('story')}
function ending(){const top=Object.entries(S.relations).sort((a,b)=>b[1]-a[1]).slice(0,2);return `${shellTitle('Épilogue','La dernière <em>page</em>','La fin de cette chronique n’efface rien de ce qui l’a précédée. Elle rassemble les personnes, les promesses et les décisions qui t’ont construit.') }<div class="content"><div class="card"><div class="eyebrow">Sept années plus tard</div><h2>${esc(S.character.name)}, ${esc(S.character.house)}</h2><p class="story-copy">Tu es arrivé à Poudlard avec une lettre, des questions et une idée encore floue de la personne que tu deviendrais. Tu repars avec une histoire qui ne ressemble à aucune autre : faite de choix imparfaits, de liens éprouvés et de découvertes qui t’appartiennent.</p><p>Ta réputation auprès des élèves : ${S.reputation.students}. Auprès des professeurs : ${S.reputation.professors}. Points gagnés par ta maison : ${S.housePoints}. Tes choix ont façonné une réputation qui ne se résume pas à un score.</p><p>${S.flags.darkMagicUsed?'Tu as utilisé une magie risquée. Certaines personnes s’en souviendront, même si tu as agi pour une raison que toi seul peux pleinement expliquer.':S.flags.darkMagicStudied?'Tu as étudié les limites de la magie interdite sans lui confier toutes tes décisions.':'Tu as choisi ta manière de faire face aux situations difficiles.'} ${S.patronusStage>=3?'Ton Patronus, '+esc(S.character.patronus)+', demeure le symbole d’un souvenir qui t’a aidé à avancer.':'Le Patronus reste une étape inachevée de ton apprentissage, une possibilité que tu pourras explorer dans une autre chronique.'}</p><p>Décisions majeures consignées : ${S.choices.length}. Indices recueillis : ${S.clues.length}. Sorts connus : ${S.spells.length}. Épreuves passées : ${Object.keys(S.flags).filter(k=>k.startsWith('exam_')&&S.flags[k]).length}. Défis de maison : ${Object.keys(S.flags).filter(k=>k.startsWith('houseChallenge_')&&S.flags[k]).length}/7. Victoires de Quidditch : ${S.quidditch.wins||0}.</p><p>${S.housePoints>=50?'Ta maison se souviendra de ta contribution remarquable : tes points ont pesé dans la course à la Coupe.':S.housePoints>=20?'Tu as contribué régulièrement à la vie de ta maison, même si tous tes efforts n’ont pas été récompensés par des points.':'Tu as privilégié les relations, les découvertes ou tes propres objectifs plutôt que la course aux points.'} ${S.reputation.professors>=4?'Plusieurs professeurs reconnaissent ton sérieux.':S.reputation.professors<=-2?'Certains professeurs gardent des réserves sur tes décisions.':'Tes relations avec les professeurs restent nuancées.'}</p><p>${S.flags.investigationProgress>=2?'Tu as recoupé plusieurs indices et appris à distinguer une preuve d’une hypothèse.':S.clues.length>=2?'Tu as conservé plusieurs pistes, dont certaines pourraient être confirmées dans une autre chronique.':'Tu as privilégié d’autres chemins ; certaines questions restent ouvertes.'}</p><h3>Les liens qui t’ont accompagné</h3>${top.map(([n,v])=>`<div class="listrow"><div class="listicon">♡</div><div><strong>${esc(n)}</strong><p>${v>2?'Une confiance solide s’est construite.':v>0?'Un lien positif s’est développé.':v<0?'Une relation marquée par la méfiance.':'Une relation qui reste à écrire.'}</p></div></div>`).join('')}<div class="btnrow"><button class="btn primary" onclick="navigate('journal')">Relire ma chronique</button><button class="btn" onclick="startCreation()">Commencer une autre histoire</button></div></div></div>`}
function mapPage(){return `${shellTitle('Explorer','Les lieux de <em>Poudlard</em>','Le château se découvre selon ton année, les occasions et les pistes que tu choisis de suivre.')}<div class="content wide"><div class="card"><div class="eyebrow">Carte narrative</div><p class="muted small">Sélectionne un lieu pour lire sa description et découvrir les activités accessibles. Certains endroits restent fermés tant que l’histoire ne t’y conduit pas.</p><div class="mapgrid">${LOCATIONS.map((l,i)=>{let unlocked=S.started&&S.year>=l.unlock;return `<button class="tile ${unlocked?'':'locked'}" ${unlocked?`onclick="visitLocation(${i})"`:''}><span class="tileicon">${l.icon}</span><strong>${esc(l.name)}</strong><small>${unlocked?esc(l.desc):`Accessible à partir de l’année ${l.unlock}`}</small></button>`}).join('')}</div></div><div class="notice">La carte utilise des lieux narratifs et des conditions d’accès. Les passages secrets se débloquent par tes découvertes, pas par un clic arbitraire.</div></div>`}
function visitLocation(i){if(!S.started)return toast('Commence ton aventure pour explorer.');const l=LOCATIONS[i];if(!l||S.year<l.unlock)return;const visitKey=`visit_${S.year}_${i}`;if(S.flags[visitKey])return showModal(l.name,'Tu as déjà exploré ce lieu pendant cette année. Les découvertes uniques ne se répètent pas, mais tu peux revenir l’année prochaine.',()=>render());S.flags[visitKey]=true;let text=l.desc;let action='';if(l.name==='Bibliothèque'){S.skills.Sortilèges++;S.journal.push(`Tu as passé du temps à la bibliothèque pendant l’année ${S.year}.`);action='<br><br>En parcourant un registre, tu notes une référence à consulter plus tard. Ta compétence en Sortilèges progresse légèrement.'}else if(l.name==='Salle de classe'){S.magic=Math.min(100,S.magic+10);S.skills.Défense++;action='<br><br>Un exercice t’aide à affiner ta technique. Ton énergie magique se restaure un peu.'}else if(l.name==='Terrain de Quidditch'){S.quidditch.trained++;S.reputation.students++;action='<br><br>Tu prends le temps de t’entraîner. Ton sens du jeu et ta réputation progressent.'}else if(l.name==='Salle commune'){S.health=Math.min(100,S.health+10);S.magic=Math.min(100,S.magic+15);const houseScene={Gryffondor:'Le feu crépite près des fauteuils rouges et or. Un groupe discute d’un défi de courage qui pourrait devenir une quête de maison.',Serpentard:'La lumière verte du lac glisse sur les murs. Une conversation discrète laisse entendre qu’un élève connaît un passage utile, mais attend de voir si tu sais garder un secret.',Serdaigle:'Les étagères et les notes couvertes de signes attirent ton attention. Une énigme laissée sur un tableau semble destinée à quelqu’un qui aime chercher.',Poufsouffle:'L’atmosphère chaleureuse invite à partager un thé. Un camarade te propose d’aider à retrouver un objet perdu, et sa gratitude pourrait renforcer votre lien.'};text=houseScene[S.character.house]||text;const flag='commonRoom_'+S.year;if(!S.flags[flag]){S.flags[flag]=true;S.quests.push({title:'Un secret de la salle commune',description:`Une occasion propre à ${S.character.house} t’attend : explore les liens et les habitudes de ta maison.`});S.journal.push(`Année ${S.year} — Tu as découvert une piste propre à la salle commune de ${S.character.house}.`)}action='<br><br>Tu te reposes : santé et énergie magique récupérées. Une piste exclusive à ta maison a été ajoutée à ton journal de quêtes.'}else if(l.name==='Parc et lac'){S.journal.push(`Tu as pris un moment de calme près du lac en année ${S.year}.`);action='<br><br>Le calme du lieu te permet de remettre tes idées en ordre.'}else if(l.name==='Pré-au-Lard'){action=`<br><br>Les boutiques sont ouvertes. Tu disposes de ${S.galleons} gallions.`}showModal(l.name,text+action,()=>{autoSave();render()})}
function journalPage(){return `${shellTitle('Ta mémoire','Journal <em>personnel</em>','Une chronique de tes choix, de tes découvertes et des promesses que tu as décidé de garder.') }<div class="content">${!S.started?`<div class="card empty"><div class="big">▤</div><h2>Les pages sont vierges</h2><p class="muted">Commence l’aventure pour écrire ta chronique.</p></div>`:`<div class="card"><div class="eyebrow">Événements consignés</div><h2>${S.journal.length} entrée${S.journal.length===1?'':'s'}</h2>${S.journal.length?S.journal.slice().reverse().map((x,i)=>`<div class="listrow"><div class="listicon">✧</div><div><strong>${esc(x.split(' — ')[0]||'Chronique')}</strong><p>${esc(x.includes(' — ')?x.split(' — ').slice(1).join(' — '):x)}</p></div></div>`).join(''):'<p class="muted">Tes premières décisions seront consignées ici.</p>'}</div><div class="card"><div class="eyebrow">Carnet d’enquête</div><h2>Indices recueillis</h2>${S.clues.length?S.clues.map(x=>`<div class="listrow"><div class="listicon">⌕</div><div><strong>Indice découvert</strong><p>${esc(x)}</p></div></div>`).join(''):'<p class="muted">Les indices apparaîtront ici lorsque tu en découvriras au cours de tes explorations.</p>'}</div><div class="card"><div class="eyebrow">Choix mémorables</div>${S.choices.length?S.choices.slice().reverse().map(c=>`<div class="listrow"><div class="listicon">↳</div><div><strong>Année ${c.year} · ${esc(c.title)}</strong><p>Tu as choisi : ${esc(c.choice)}</p></div></div>`).join(''):'<p class="muted">Tes décisions importantes apparaîtront ici.</p>'}</div>`}</div>`}
function profilePage(){if(!S.started)return `${shellTitle('Personnage','Ton profil <em>magique</em>','Ta fiche personnelle sera disponible après la cérémonie de répartition.')}<div class="content card"><button class="btn primary" onclick="startCreation()">Créer mon personnage</button></div>`;const c=S.character;return `${shellTitle('Personnage','La fiche de <em>${esc(c.name)}</em>','Une identité qui évolue au fil des cours, des liens et des décisions.') }<div class="content"><div class="card"><div class="scene-top"><span class="pill">Année ${S.year} sur 7</span><span class="pill">${esc(c.house)}</span></div><h2>${HOUSES[c.house]?.crest||'✧'} ${esc(c.name)}</h2><p class="muted">${esc(c.appearance||'Apparence à découvrir')} · ${esc(c.pronouns||'Pronoms non précisés')}</p><div class="statrow">${stat('Santé',S.health+'%')}${stat('Magie',S.magic+'%')}${stat('Gallions',S.galleons)}${stat('Points maison',S.housePoints)}</div><div class="divider"></div><div class="grid2"><div><div class="eyebrow">Personnalité</div><p>${esc(c.personality||'Évolutive')}</p><p class="muted small">Qualité : ${esc(c.qualities.join(', ')||'à découvrir')}<br>Défaut : ${esc(c.flaws.join(', ')||'à découvrir')}</p></div><div><div class="eyebrow">Origines et ambitions</div><p>${esc(c.family||'Origines à préciser')}</p><p class="muted small">${esc(c.ambition||'Ambition en devenir')}</p></div></div><div class="divider"></div><div class="eyebrow">Progression générale</div><p class="muted small">${S.choices.length} choix consignés · ${S.clues.length} indices · ${S.quests.filter(q=>q&&typeof q==='object'&&q.completed).length} quêtes validées · ${S.spells.length} sorts connus</p><div class="eyebrow">Compétences acquises</div>${Object.entries(S.skills).map(([k,v])=>`<div class="listrow"><div class="listicon">✧</div><div style="flex:1"><strong>${esc(k)}</strong><div class="progress"><span style="width:${Math.min(100,v*12+8)}%"></span></div></div><span class="muted small">${v}</span></div>`).join('')}<div class="divider"></div><div class="eyebrow">Baguette et compagnon</div><p>${esc(c.wood||'Bois à découvrir')} · ${esc(c.core||'Cœur à découvrir')} · ${esc(c.length||'Longueur à découvrir')} · ${esc(c.flexibility||'Souplesse à découvrir')}</p><p class="muted small">Compagnon : ${esc(c.animal||'À choisir')}</p><div class="eyebrow">Patronus</div><p>${S.patronusStage>=3?`Forme révélée : ${esc(c.patronus)}`:S.patronusStage>0?'Une lueur argentée commence à répondre à tes souvenirs.':'Encore à découvrir au fil de l’histoire.'}</p></div></div>`}
function relationsPage(){return `${shellTitle('Liens et réputation','Les personnes <em>comptent</em>','La confiance se construit avec le temps. Certaines blessures ne disparaissent pas d’un simple dialogue.') }<div class="content"><div class="card"><div class="eyebrow">Relations</div>${Object.entries(S.relations).map(([name,v])=>`<div class="listrow"><div class="listicon">${v>=2?'♡':v<0?'◇':'·'}</div><div style="flex:1"><strong>${esc(name)}</strong><p>${v>=4?'Confiance profonde':v>=2?'Lien positif':v>0?'Premiers liens':v===0?'Relation à construire':v<=-3?'Rivalité profonde':'Méfiance ou tension'}</p><div class="progress"><span style="width:${Math.max(4,((v+5)/15)*100)}%;background:${v<0?'#a75b65':'var(--gold)'}"></span></div></div><span class="muted small">${v>0?'+':''}${v}</span></div>`).join('')}</div><div class="card"><div class="eyebrow">Réputation dynamique</div><div class="grid3">${Object.entries(S.reputation).map(([k,v])=>`<div class="stat"><div class="label">${k==='students'?'Élèves':k==='professors'?'Professeurs':'Maison'}</div><strong>${v>0?'+':''}${v}</strong></div>`).join('')}</div><p class="muted small">Tes actes, résultats et secrets peuvent modifier la façon dont les élèves, les professeurs et ta maison te perçoivent.</p></div></div>`}
function spellsPage(){return `${shellTitle('Grimoire','Sorts et <em>maîtrise</em>','Les sortilèges s’apprennent par la pratique, les cours, les livres et les rencontres. Leur maîtrise se construit naturellement.') }<div class="content wide"><div class="card"><div class="eyebrow">Sorts connus</div><div class="grid2">${SPELLS.map(sp=>{const known=S.spells.includes(sp.name);const unlocked=S.year>=sp.unlock;return `<div class="card slim"><div class="scene-top"><span class="pill">${known?'Maîtrisé':unlocked?'À apprendre':`Année ${sp.unlock}+`}</span><span class="muted small">${sp.cost} énergie</span></div><h3>${known?'✧ ':unlocked?'◇ ':'⌑ '}${esc(sp.name)}</h3><p class="muted small">${esc(sp.desc)}</p>${known?`<button class="btn" onclick="castSpell('${sp.name}')">Pratiquer</button>`:unlocked?`<button class="btn primary" onclick="learnSpell('${sp.name}')">S’entraîner</button>`:`<button class="btn" disabled>Pas encore accessible</button>`}</div>`}).join('')}</div></div><div class="card"><div class="eyebrow">Progression spéciale</div><h2>Le Patronus</h2><p class="muted">${S.patronusStage===0?'Son apprentissage viendra avec les expériences qui donnent du sens à tes souvenirs.':S.patronusStage===1?'Une lueur fragile a répondu à un souvenir important.':S.patronusStage===2?'Ta magie prend une forme plus stable, mais la révélation complète demande encore du chemin.':'Ton Patronus a révélé sa forme : '+esc(S.character.patronus)+'.'}</p><div class="progress"><span style="width:${S.patronusStage/3*100}%"></span></div></div></div>`}
function learnSpell(name){if(!S.started)return toast('Commence ton aventure avant d’apprendre des sorts.');const sp=SPELLS.find(x=>x.name===name);if(!sp||S.year<sp.unlock)return;if(S.spells.includes(name)){toast('Ce sort figure déjà dans ton grimoire. Entraîne-toi à le maîtriser.');return}if(S.magic<8){toast('Ton énergie magique est trop faible pour t’entraîner.');return}S.magic=Math.max(0,S.magic-8);S.spells.push(name);S.skills.Sortilèges++;S.journal.push(`Année ${S.year} — Tu as appris ${name}.`);autoSave();render();toast(`${name} ajouté à ton grimoire.`)}
function castSpell(name){if(!S.started)return toast('Commence ton aventure avant de lancer des sorts.');const sp=SPELLS.find(x=>x.name===name);if(!sp||!S.spells.includes(name))return toast('Ce sort ne figure pas dans ton grimoire.');if(name==='Nox'){toast('Ta baguette s’éteint.');return}if(S.magic<sp.cost){toast('Pas assez d’énergie magique. Repose-toi dans ta salle commune.');return}S.magic-=sp.cost;S.skills.Sortilèges++;if(name==='Lumos')toast('Une lumière douce jaillit de ta baguette.');else if(name==='Protego')toast('Un bouclier translucide se forme un instant.');else if(name==='Expecto Patronum'){if(S.patronusStage<2){toast('Concentre-toi sur un souvenir plus fort : ton Patronus reste incomplet.')}else{S.patronusStage=3;S.character.patronus=derivePatronus();S.journal.push(`Année ${S.year} — Ton Patronus a révélé sa forme : ${S.character.patronus}.`);showModal('Expecto Patronum',`La lumière argentée s’élève, hésite, puis prend une forme reconnaissable : <strong>${esc(S.character.patronus)}</strong>. Ce n’est pas un symbole de ta maison, mais le reflet de ton propre parcours.`,()=>{autoSave();render()});return}}else toast(`${name} est lancé avec succès.`);autoSave();render()}
function derivePatronus(){const q=S.character.qualities[0]||'Courage';const map={'Courage':'Loup','Curiosité':'Renard','Loyauté':'Chien','Persévérance':'Cheval','Ingéniosité':'Loutre','Empathie':'Cerf'};return map[q]||'Loup'}
function inventoryPage(){return `${shellTitle('Objets et trouvailles','Ton <em>inventaire</em>','Les objets peuvent aider à explorer, apprendre ou comprendre certains mystères. Les trouvailles rares auront une histoire propre.') }<div class="content"><div class="card"><div class="eyebrow">Objets possédés</div>${S.inventory.length?S.inventory.map((item,i)=>`<div class="listrow"><div class="listicon">${item.includes('Baguette')?'✧':item.includes('Carnet')?'▤':'♧'}</div><div style="flex:1"><strong>${esc(item)}</strong><p>${item==='Baguette magique'?'Ton instrument personnel, adapté à ta découverte du monde magique.':item==='Carnet personnel'?'Tes notes, tes hypothèses et les souvenirs que tu veux garder.':item==='Uniforme de Poudlard'?'La tenue nécessaire à ta vie scolaire.':item.startsWith('Potion')?'Une préparation consommable qui restaure une ressource ou aide avant un défi.':item==='Ingrédients de potion'?'Un lot d’ingrédients pour tes préparations.':item==='Livre de révision'?'Un ouvrage pratique pour progresser dans plusieurs matières.':'Un objet recueilli au fil de l’aventure.'}</p>${['Potion de soin','Potion de concentration','Potion de protection','Livre de révision','Ingrédients de potion','Carnet d’enquête','Guide des symboles anciens','Friandise pour créature'].includes(item)?`<button class="btn" onclick="useItem(${i})">Utiliser</button>`:''}</div></div>`).join(''):'<p class="muted">Ton inventaire est vide.</p>'}</div><div class="card"><div class="eyebrow">Économie</div><h2>${S.galleons} gallions</h2><p class="muted small">Les récompenses et les dépenses apparaîtront au fil des quêtes. Les achats ne doivent jamais bloquer la progression principale.</p><div class="btnrow"><button class="btn" onclick="rest()">Se reposer · gratuit</button><button class="btn" onclick="buyPotion()">Acheter une potion · 5 gallions</button></div></div></div>`}
function rest(){if(!S.started)return toast('Commence ton aventure avant de te reposer.');const key=`rest_${S.year}_${S.chapter}`;if(S.flags[key])return toast('Tu as déjà pris un temps de repos pendant ce chapitre.');S.flags[key]=true;S.health=Math.min(100,S.health+25);S.magic=Math.min(100,S.magic+30);S.journal.push(`Année ${S.year} — Tu as pris le temps de te reposer.`);autoSave();render();toast('Santé et énergie restaurées.')}function buyPotion(){if(!S.started)return toast('Commence ton aventure avant de faire des achats.');if(S.galleons<5){toast('Tu n’as pas assez de gallions.');return}S.galleons-=5;S.inventory.push('Potion de soin');toast('Potion ajoutée à ton inventaire.');autoSave();render()}
function savesPage(){const slots=getSlots();return `${shellTitle('Chroniques conservées','Sauvegardes <em>magiques</em>','Cinq emplacements indépendants. Tu peux aussi exporter une partie pour la transférer vers un autre appareil.') }<div class="content"><div class="card"><div class="eyebrow">Emplacements</div>${slots.map((x,i)=>`<div class="chapter-item"><div><strong>Emplacement ${i+1}</strong><div class="muted small">${x?`${esc(x.character?.name||'Personnage')} · ${esc(x.character?.house||'Maison inconnue')} · Année ${x.year||1} · ${x.lastSave?new Date(x.lastSave).toLocaleString('fr-FR'):'Sauvegarde disponible'}`:'Emplacement vide'}</div></div><div class="btnrow" style="margin:0">${x?`<button class="btn" onclick="loadSlot(${i})">Charger</button><button class="btn primary" onclick="saveSlotConfirm(${i})">Remplacer par la partie actuelle</button><button class="btn" onclick="exportSlot(${i})">Exporter</button><button class="btn" onclick="deleteSlot(${i})">Supprimer</button>`:`<button class="btn primary" onclick="saveSlot(${i})">Enregistrer ici</button>`}</div></div>`).join('')}</div><div class="card"><div class="eyebrow">Importer une partie</div><p class="muted small">Sélectionne un fichier JSON exporté depuis Destin de Poudlard. Les données seront vérifiées avant chargement.</p><input type="file" accept="application/json,.json" id="importFile" style="max-width:100%;color:var(--muted)"><div class="btnrow"><button class="btn primary" onclick="importSlot()">Importer le fichier</button></div></div><div class="notice">Les sauvegardes restent dans le stockage local de ce navigateur. Pour jouer sur un autre appareil, exporte puis importe un fichier.</div></div>`}
function getSlots(){let a=safeJSON(localStorage.getItem('dp_slots'));return Array.isArray(a)?Array.from({length:5},(_,i)=>a[i]||null):[null,null,null,null,null]}
function saveSlotConfirm(i){const slots=getSlots();if(slots[i]&&S.settings.confirm&&!confirm(`Remplacer la sauvegarde ${i+1} par la partie actuelle ? Cette action écrase l’ancienne version.`))return;saveSlot(i)}
function validSaveData(data){return !!(data&&typeof data==='object'&&!Array.isArray(data)&&data.character&&typeof data.character==='object'&&typeof data.started==='boolean'&&Number.isInteger(data.year)&&data.year>=1&&data.year<=7&&Number.isInteger(data.chapter)&&data.chapter>=0&&data.chapter<YEARS[data.year-1].length&&Array.isArray(data.inventory)&&data.inventory.every(x=>typeof x==='string')&&Array.isArray(data.choices)&&Array.isArray(data.journal)&&data.journal.every(x=>typeof x==='string')&&Array.isArray(data.clues||[])&&(data.clues||[]).every(x=>typeof x==='string')&&data.relations&&typeof data.relations==='object'&&!Array.isArray(data.relations)&&data.skills&&typeof data.skills==='object'&&!Array.isArray(data.skills))}
function saveSlot(i){if(!Number.isInteger(i)||i<0||i>4){toast('Emplacement invalide.');return}const slots=getSlots();S.lastSave=new Date().toISOString();slots[i]=JSON.parse(JSON.stringify(S));localStorage.setItem('dp_slots',JSON.stringify(slots));activeSlot=i;localStorage.setItem('dp_active',String(i));toast(`Partie enregistrée dans l’emplacement ${i+1}.`);render()}
function autoSave(){try{const slots=getSlots();let i=Number(localStorage.getItem('dp_active')||activeSlot||0);if(!Number.isInteger(i)||i<0||i>4)i=0;S.lastSave=new Date().toISOString();slots[i]=JSON.parse(JSON.stringify(S));localStorage.setItem('dp_slots',JSON.stringify(slots));localStorage.setItem('dp_active',String(i));}catch(e){console.warn('Sauvegarde automatique impossible',e)}}
function manualSave(){if(!S.started){toast('Commence une aventure avant de sauvegarder.');navigate('saves');return}const slots=getSlots();const i=Number(localStorage.getItem('dp_active')||activeSlot||0);saveSlot(Math.min(4,Math.max(0,i)));}
function loadSlot(i){if(!Number.isInteger(i)||i<0||i>4)return;const slots=getSlots();if(!slots[i])return;const data=slots[i];if(!validSaveData(data)){toast('Cette sauvegarde ne semble pas valide ou est incomplète.');return}S={...initialState(),...data,settings:{...DEFAULT_SETTINGS,...data.settings}};activeSlot=i;localStorage.setItem('dp_active',String(i));setTheme();navigate(S.started?'home':'create');toast('Sauvegarde chargée.');}
function deleteSlot(i){if(!Number.isInteger(i)||i<0||i>4)return;if(S.settings.confirm&&!confirm(`Supprimer définitivement la sauvegarde ${i+1} ?`))return;const slots=getSlots();slots[i]=null;localStorage.setItem('dp_slots',JSON.stringify(slots));render();toast('Sauvegarde supprimée.')}
function exportSlot(i){if(!Number.isInteger(i)||i<0||i>4)return;const slots=getSlots(),data=slots[i]||S;const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`destin-poudlard-${(data.character?.name||'sauvegarde').toLowerCase().replace(/[^a-z0-9-]/g,'-')}.json`;a.click();URL.revokeObjectURL(url);toast('Export de la sauvegarde préparé.')}
function importSlot(){const f=$('importFile').files[0];if(!f){toast('Choisis d’abord un fichier JSON.');return}const r=new FileReader();r.onload=()=>{const data=safeJSON(r.result);if(!validSaveData(data)){toast('Fichier invalide, incomplet ou incompatible.');return}S={...initialState(),...data,settings:{...DEFAULT_SETTINGS,...data.settings}};setTheme();autoSave();navigate(S.started?'home':'create');toast('Sauvegarde importée.');};r.readAsText(f)}
function settingsPage(){return `${shellTitle('Confort de lecture','Paramètres <em>personnels</em>','Ajuste l’interface à tes préférences. Ces réglages sont conservés séparément de tes parties.') }<div class="content"><div class="card"><div class="field"><label for="fontScale">Taille du texte : ${Math.round(S.settings.fontScale*100)}%</label><input id="fontScale" type="range" min="0.85" max="1.3" step="0.05" value="${S.settings.fontScale}" oninput="updateSetting('fontScale',Number(this.value),false)"></div><div class="field"><label for="reading">Largeur de lecture : ${S.settings.reading}px</label><input id="reading" type="range" min="600" max="1000" step="20" value="${S.settings.reading}" oninput="updateSetting('reading',Number(this.value),false)"></div><div class="field"><label for="contrast">Contraste renforcé</label><select id="contrast" onchange="updateSetting('contrast',this.value==='true')"><option value="false" ${!S.settings.contrast?'selected':''}>Désactivé</option><option value="true" ${S.settings.contrast?'selected':''}>Activé</option></select></div><div class="field"><label for="reduced">Animations</label><select id="reduced" onchange="updateSetting('reduced',this.value==='true')"><option value="false" ${!S.settings.reduced?'selected':''}>Animations discrètes</option><option value="true" ${S.settings.reduced?'selected':''}>Réduire les animations</option></select></div><div class="field"><label for="dialogueSpeed">Affichage des dialogues</label><select id="dialogueSpeed" onchange="updateSetting('dialogueSpeed',this.value)"><option value="slow" ${S.settings.dialogueSpeed==='slow'?'selected':''}>Lent</option><option value="normal" ${S.settings.dialogueSpeed==='normal'?'selected':''}>Normal</option><option value="fast" ${S.settings.dialogueSpeed==='fast'?'selected':''}>Rapide</option></select></div><div class="field"><label for="confirm">Confirmations avant suppression</label><select id="confirm" onchange="updateSetting('confirm',this.value==='true')"><option value="true" ${S.settings.confirm?'selected':''}>Demander confirmation</option><option value="false" ${!S.settings.confirm?'selected':''}>Ne pas demander</option></select></div><div class="btnrow"><button class="btn" onclick="resetSettings()">Réinitialiser les réglages</button><button class="btn primary" onclick="saveSettings()">Enregistrer les préférences</button></div></div><div class="notice">Le site fonctionne sans compte ni serveur. Le stockage local peut être effacé par le navigateur : exporte régulièrement tes sauvegardes importantes.</div></div>`}
function updateSetting(k,v,save=true){S.settings[k]=v;setTheme();if(save){localStorage.setItem('dp_settings',JSON.stringify(S.settings));if(S.page==='settings')render()}}
function saveSettings(){localStorage.setItem('dp_settings',JSON.stringify(S.settings));setTheme();toast('Préférences enregistrées.');render()}
function resetSettings(){S.settings={...DEFAULT_SETTINGS};localStorage.setItem('dp_settings',JSON.stringify(S.settings));setTheme();render();toast('Réglages réinitialisés.')}
function showModal(title,html,onClose){$('modalroot').innerHTML=`<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><div><div class="eyebrow">Destin de Poudlard</div><h2 style="font:500 30px var(--serif);margin:4px 0 15px">${esc(title)}</h2></div><button class="close" onclick="closeModal()" aria-label="Fermer">×</button></div><div>${html}</div><div class="btnrow"><button class="btn primary" id="modalContinue">Continuer →</button></div></div></div>`;$('modalroot').querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});$('modalContinue').onclick=()=>{closeModal();if(onClose)onClose()};}
function closeModal(){$('modalroot').innerHTML=''}
function render(){setTheme();saveSession();const main=$('main');let page=S.page||'home';if(page==='home')main.innerHTML=home();else if(page==='create')main.innerHTML=createPage();else if(page==='sorting')main.innerHTML=sorting();else if(page==='story')main.innerHTML=story();else if(page==='ending')main.innerHTML=ending();else if(page==='map')main.innerHTML=mapPage();else if(page==='activities')main.innerHTML=activitiesPage();else if(page==='journal')main.innerHTML=journalPage();else if(page==='profile')main.innerHTML=profilePage();else if(page==='relations')main.innerHTML=relationsPage();else if(page==='spells')main.innerHTML=spellsPage();else if(page==='inventory')main.innerHTML=inventoryPage();else if(page==='saves')main.innerHTML=savesPage();else if(page==='settings')main.innerHTML=settingsPage();else main.innerHTML=home();navActive();}
(function init(){const settings=safeJSON(localStorage.getItem('dp_settings'));if(settings)S.settings={...DEFAULT_SETTINGS,...settings};const session=safeJSON(localStorage.getItem('dp_session'));const slots=getSlots();const idx=Number(localStorage.getItem('dp_active')||0);if(session&&typeof session==='object'&&session.character){S={...initialState(),...session,settings:{...DEFAULT_SETTINGS,...S.settings,...session.settings}};activeSlot=Number.isInteger(idx)&&idx>=0&&idx<5?idx:0}else if(slots[idx]){S={...initialState(),...slots[idx],settings:{...DEFAULT_SETTINGS,...S.settings,...slots[idx].settings}};activeSlot=idx}else{S.page='home'}S.page=document.body.dataset.page||'home';setTheme();render()})();
